#[derive(Debug, Clone, Copy, Serialize, Default, PartialEq)]
struct LiveAudioInputLevels {
    running: bool,
    stale: bool,
    safety_clear_pending: bool,
    bass: f32,
    mid: f32,
    high: f32,
    bands: [f32; audio::live_features::MAX_LIVE_AUDIO_BANDS],
    band_count: usize,
    rms: f32,
    peak: f32,
    spectral_flux: f32,
    spectral_centroid: f32,
    spectral_density_fast: f32,
    spectral_density_slow: f32,
    kick_strength: f32,
    snare_strength: f32,
    kick_event: bool,
    snare_event: bool,
    onset: bool,
    onset_strength: f32,
    bpm: Option<f32>,
    bpm_confidence: f32,
    beat_phase: f32,
    feature_sequence: u64,
}

impl LiveAudioInputLevels {
    fn from_status(status: &LiveAudioInputStatus) -> Self {
        let safe = status.running && !status.stale && !status.safety_clear_pending;
        let level = |value: f32| {
            if safe && value.is_finite() {
                value.clamp(0.0, 1.0)
            } else {
                0.0
            }
        };
        let band_count = if safe {
            status
                .band_count
                .min(audio::live_features::MAX_LIVE_AUDIO_BANDS)
        } else {
            0
        };
        let mut bands = [0.0; audio::live_features::MAX_LIVE_AUDIO_BANDS];
        for (target, source) in bands.iter_mut().zip(status.bands).take(band_count) {
            *target = level(source);
        }
        Self {
            running: status.running,
            stale: status.stale,
            safety_clear_pending: status.safety_clear_pending,
            bass: level(status.bass),
            mid: level(status.mid),
            high: level(status.high),
            bands,
            band_count,
            rms: level(status.rms),
            peak: level(status.peak),
            spectral_flux: level(status.spectral_flux),
            spectral_centroid: level(status.spectral_centroid),
            spectral_density_fast: level(status.spectral_density_fast),
            spectral_density_slow: level(status.spectral_density_slow),
            kick_strength: level(status.kick_strength),
            snare_strength: level(status.snare_strength),
            kick_event: safe && status.kick_event,
            snare_event: safe && status.snare_event,
            onset: safe && status.onset,
            onset_strength: level(status.onset_strength),
            bpm: safe
                .then_some(status.bpm)
                .flatten()
                .filter(|bpm| bpm.is_finite() && *bpm > 0.0),
            bpm_confidence: level(status.bpm_confidence),
            beat_phase: if safe && status.beat_phase.is_finite() {
                status.beat_phase.rem_euclid(1.0)
            } else {
                0.0
            },
            feature_sequence: if safe { status.feature_sequence } else { 0 },
        }
    }
}

const LIVE_AUDIO_STALE_AFTER: Duration = Duration::from_millis(250);
const LIVE_AUDIO_RECEIVE_POLL_INTERVAL: Duration = Duration::from_millis(50);
const LIVE_AUDIO_MAX_CONFIGURED_BUFFER_AGE: Duration = Duration::from_millis(200);
const LIVE_AUDIO_STOP_CLEAR_RETRY: Duration = Duration::from_millis(100);
const LIVE_AUDIO_STOP_CLEAR_RETRY_INTERVAL: Duration = Duration::from_millis(2);
const LIVE_AUDIO_CAPTURE_SLOT_COUNT: usize = 4;
const LIVE_AUDIO_CAPTURE_SLOT_FRAMES: usize = 2_048;
const _: [(); LIVE_AUDIO_CAPTURE_SLOT_COUNT] = [(); protocol::MAX_LIVE_AUDIO_FRAME_ONSETS];
const _: [(); audio::live_features::MAX_LIVE_AUDIO_BANDS] =
    [(); protocol::LIVE_AUDIO_FEATURE_BAND_CAPACITY];
static NEXT_LIVE_AUDIO_GENERATION: AtomicU64 = AtomicU64::new(1);

fn allocate_live_audio_generation() -> Result<u64, String> {
    let generation = NEXT_LIVE_AUDIO_GENERATION.fetch_add(1, Ordering::Relaxed);
    if generation == 0 {
        Err("Live audio input generation counter was exhausted".to_string())
    } else {
        Ok(generation)
    }
}

fn rotate_live_audio_generation(active: &AtomicU64) -> Result<u64, String> {
    let generation = allocate_live_audio_generation()?;
    active.store(generation, Ordering::Release);
    Ok(generation)
}
const LIVE_AUDIO_STALE_ERROR: &str = "Live audio input is stale: no samples received for 250 ms";
const LIVE_AUDIO_WORKER_STALE_ERROR: &str =
    "Live audio input is stale: FFT worker heartbeat exceeded 250 ms";
const LIVE_AUDIO_ONSET_QUEUE_OVERFLOW_ERROR: &str =
    "Live audio onset queue exceeded its fixed real-time capacity";
const LIVE_AUDIO_TERMINAL_SOURCE_WASAPI_STREAM: u32 = 1;
const LIVE_AUDIO_TERMINAL_SOURCE_WASAPI_ADAPTER: u32 = 2;
const LIVE_AUDIO_TERMINAL_SOURCE_ASIO_BRIDGE: u32 = 3;
const LIVE_AUDIO_TERMINAL_SOURCE_ASIO_ADAPTER: u32 = 4;
const LIVE_AUDIO_TERMINAL_KIND_DEVICE_NOT_AVAILABLE: u32 = 1;
const LIVE_AUDIO_TERMINAL_KIND_BACKEND_SPECIFIC: u32 = 2;
const LIVE_AUDIO_TERMINAL_KIND_ADAPTER_PANIC: u32 = 1;
const LIVE_AUDIO_TERMINAL_EVENT_HANDLED: u64 = u64::MAX;

#[derive(Debug, Clone, Copy, Serialize, Deserialize, Default, PartialEq, Eq)]
#[serde(tag = "mode", rename_all = "snake_case")]
enum LiveAudioChannelMix {
    #[default]
    AverageAll,
    Single {
        channel_index: u16,
    },
    StereoPair {
        left_channel_index: u16,
        right_channel_index: u16,
    },
}

impl LiveAudioChannelMix {
    fn validate(self, channels: u16) -> Result<(), String> {
        if channels == 0 {
            return Err("Live audio stream must expose at least one channel".to_string());
        }
        let validate_index = |index: u16, label: &str| {
            if index < channels {
                Ok(())
            } else {
                Err(format!(
                    "Live audio {label} channel index {index} is outside the configured {channels}-channel stream"
                ))
            }
        };
        match self {
            Self::AverageAll => Ok(()),
            Self::Single { channel_index } => validate_index(channel_index, "single"),
            Self::StereoPair {
                left_channel_index,
                right_channel_index,
            } => {
                validate_index(left_channel_index, "left")?;
                validate_index(right_channel_index, "right")?;
                if left_channel_index == right_channel_index {
                    return Err(
                        "Live audio stereo-pair channels must use two different indices"
                            .to_string(),
                    );
                }
                Ok(())
            }
        }
    }
}

