const VISUALIZER_MODEL_ASSET_CACHE_LIMIT: usize = 64;
const AUDIO_FILE_EXTENSIONS: &[&str] = &[
    "wav", "mp3", "m4a", "aac", "flac", "aiff", "aif", "ogg", "opus",
];
const ARTNET_MAX_UNIVERSE: u16 = 32_767;
const SACN_MAX_UNIVERSE: u16 = 63_999;
