#[tauri::command]
fn update_cue_from_current(
    state: State<'_, AppState>,
    cue_id: CueId,
    label: String,
    fade_ms: u64,
    capture_scope: Option<CueCaptureScope>,
    effect_targets: Option<Vec<CueEffectTarget>>,
) -> Result<(), String> {
    let label = label.trim().to_string();
    if label.is_empty() {
        return Err("Cue label is required".to_string());
    }
    let mut snapshot = state.engine.persistence_snapshot()?;
    use_authored_video_snapshot(&mut snapshot);
    apply_programmer_preview_to_snapshot(&mut snapshot);
    let existing_cue = snapshot
        .cues
        .iter()
        .find(|cue| cue.id == cue_id)
        .ok_or_else(|| format!("Cue {cue_id} was not found"))?;
    let scope = capture_scope.unwrap_or_default();
    let captured = cue_targets_from_snapshot_with_scope(&snapshot, &scope)?;
    let explicit_effect_targets = match effect_targets {
        Some(effect_targets) => Some(copy_cue_effect_params_on_capture(
            &snapshot,
            effect_targets,
        )?),
        None => None,
    };
    if let Some(effect_targets) = explicit_effect_targets.as_deref() {
        validate_cue_effect_targets(&snapshot, effect_targets)?;
    }
    let merged =
        merge_cue_update_targets(&snapshot, cue_id, &scope, captured, explicit_effect_targets)?;
    ensure_cue_targets_present(
        &merged.0,
        &merged.1,
        &merged.2,
        &merged.3,
        &merged.4,
        !existing_cue.palette_targets.is_empty(),
        "updating",
    )?;
    let (targets, video_targets, video_output_targets, node_graph_targets, effect_targets) = merged;
    state.engine.update_cue_published(
        cue_id,
        label,
        fade_ms,
        targets,
        video_targets,
        video_output_targets,
        node_graph_targets,
        effect_targets,
    )
}

#[tauri::command]
fn set_cue_effect_targets(
    state: State<'_, AppState>,
    cue_id: CueId,
    effect_targets: Vec<CueEffectTarget>,
) -> Result<(), String> {
    let snapshot = state.engine.snapshot();
    let cue = snapshot
        .cues
        .iter()
        .find(|cue| cue.id == cue_id)
        .ok_or_else(|| format!("Cue {cue_id} was not found"))?;
    validate_cue_effect_targets(&snapshot, &effect_targets)?;
    validate_cue_effect_target_replacement(cue, &effect_targets)?;
    state
        .engine
        .set_cue_effect_targets_published(cue_id, effect_targets)
}

fn apply_programmer_preview_to_snapshot(snapshot: &mut EngineSnapshot) {
    for staged in &snapshot.programmer.values {
        if let Some(fixture) = snapshot
            .fixtures
            .iter_mut()
            .find(|fixture| fixture.id == staged.fixture_id)
        {
            if let Some(value) = fixture
                .attribute_values
                .iter_mut()
                .find(|value| value.attribute == staged.attribute)
            {
                value.value = staged.value;
            }
        }
    }
}

#[tauri::command]
fn set_cue_metadata(
    state: State<'_, AppState>,
    cue_id: CueId,
    cue_number: String,
    label: String,
    group_id: Option<String>,
    recall_mode: RecallMode,
    fade_ms: u64,
    authored_beats: Option<f32>,
    pre_wait_ms: u64,
    follow_ms: Option<u64>,
    ifcb_timing: protocol::CueIfcbTiming,
    parts: Vec<protocol::CuePartSummary>,
    mark: bool,
    mib_fixture_ids: Vec<FixtureId>,
    tracking: bool,
    notes: String,
) -> Result<(), String> {
    let cue_number = cue_number.trim().to_string();
    if cue_number.is_empty() {
        return Err("Cue number is required".to_string());
    }
    let label = label.trim().to_string();
    if label.is_empty() {
        return Err("Cue label is required".to_string());
    }
    let group_id = group_id
        .map(|group_id| normalize_group_id(&group_id))
        .transpose()?;
    validate_cue_authored_beats(authored_beats)?;
    let snapshot = state.engine.snapshot();
    if !snapshot.cues.iter().any(|cue| cue.id == cue_id) {
        return Err(format!("Cue {cue_id} was not found"));
    }
    if snapshot.cues.iter().any(|cue| {
        cue.id != cue_id
            && snapshot
                .cues
                .iter()
                .find(|candidate| candidate.id == cue_id)
                .map(|current| current.cue_list_id == cue.cue_list_id)
                .unwrap_or(false)
            && cue.cue_number == cue_number
    }) {
        return Err(format!("Cue number '{cue_number}' is already in use"));
    }
    let cue = snapshot
        .cues
        .iter()
        .find(|cue| cue.id == cue_id)
        .ok_or_else(|| format!("Cue {cue_id} was not found"))?;
    validate_cue_parts_for_summary(cue, &parts)?;
    validate_cue_mib_fixture_ids(cue, &mib_fixture_ids)?;
    state.engine.set_cue_details_published(
        cue_id,
        cue_number,
        label,
        group_id,
        recall_mode,
        fade_ms,
        authored_beats,
        pre_wait_ms,
        follow_ms,
        ifcb_timing,
        parts,
        mark,
        mib_fixture_ids,
        tracking,
        notes,
    )
}

