fn sample_effect_preset_json(preset: &str) -> Result<(&'static str, &'static str), String> {
    match preset.trim().to_ascii_lowercase().as_str() {
        "pulse" | "front-dimmer-pulse" | "front_dimmer_pulse" => Ok((
            SAMPLE_EFFECT_PRESET_PULSE_LABEL,
            SAMPLE_EFFECT_PRESET_PULSE_JSON,
        )),
        "shared" | "front-dimmer-shared" | "front_dimmer_shared" => Ok((
            SAMPLE_EFFECT_PRESET_SHARED_LABEL,
            SAMPLE_EFFECT_PRESET_SHARED_JSON,
        )),
        "wave" | "front-dimmer-wave" | "front_dimmer_wave" => Ok((
            SAMPLE_EFFECT_PRESET_WAVE_LABEL,
            SAMPLE_EFFECT_PRESET_WAVE_JSON,
        )),
        "flash" | "front-dimmer-flash" | "front_dimmer_flash" => Ok((
            SAMPLE_EFFECT_PRESET_FLASH_LABEL,
            SAMPLE_EFFECT_PRESET_FLASH_JSON,
        )),
        "random" | "front-dimmer-random" | "front_dimmer_random" => Ok((
            SAMPLE_EFFECT_PRESET_RANDOM_LABEL,
            SAMPLE_EFFECT_PRESET_RANDOM_JSON,
        )),
        "perlin" | "front-dimmer-perlin" | "front_dimmer_perlin" => Ok((
            SAMPLE_EFFECT_PRESET_PERLIN_LABEL,
            SAMPLE_EFFECT_PRESET_PERLIN_JSON,
        )),
        "chase" | "front-dimmer-chase" | "front_dimmer_chase" => Ok((
            SAMPLE_EFFECT_PRESET_CHASE_LABEL,
            SAMPLE_EFFECT_PRESET_CHASE_JSON,
        )),
        "ball" | "front-dimmer-ball" | "front_dimmer_ball" => Ok((
            SAMPLE_EFFECT_PRESET_BALL_LABEL,
            SAMPLE_EFFECT_PRESET_BALL_JSON,
        )),
        "fan" | "front-pan-fan" | "front_pan_fan" => {
            Ok((SAMPLE_EFFECT_PRESET_FAN_LABEL, SAMPLE_EFFECT_PRESET_FAN_JSON))
        }
        "circle" | "front-circle" | "front_circle" | "front-move-circle"
        | "front_move_circle" => Ok((
            SAMPLE_EFFECT_PRESET_CIRCLE_LABEL,
            SAMPLE_EFFECT_PRESET_CIRCLE_JSON,
        )),
        "curve" | "curve-saw" | "front-curve-saw" | "front_curve_saw" => Ok((
            SAMPLE_EFFECT_PRESET_CURVE_SAW_LABEL,
            SAMPLE_EFFECT_PRESET_CURVE_SAW_JSON,
        )),
        "spectrum" | "colour-spectrum" | "color-spectrum" => Ok((
            SAMPLE_EFFECT_PRESET_COLOUR_SPECTRUM_LABEL,
            SAMPLE_EFFECT_PRESET_COLOUR_SPECTRUM_JSON,
        )),
        "colour-chase" | "color-chase" | "colour-mapping" | "color-mapping" => Ok((
            SAMPLE_EFFECT_PRESET_COLOUR_CHASE_LABEL,
            SAMPLE_EFFECT_PRESET_COLOUR_CHASE_JSON,
        )),
        value => Err(format!(
            "Unknown sample effect preset '{value}'. Expected 'pulse', 'shared', 'wave', 'flash', 'random', 'perlin', 'chase', 'ball', 'fan', 'circle', 'curve', 'spectrum', or 'colour-chase'."
        )),
    }
}

fn sample_effect_bundle_jsons(preset: &str) -> Result<Vec<(&'static str, &'static str)>, String> {
    match preset.trim().to_ascii_lowercase().as_str() {
        "circle" | "front-circle" | "front_circle" => Ok(vec![(
            SAMPLE_EFFECT_PRESET_CIRCLE_LABEL,
            SAMPLE_EFFECT_PRESET_CIRCLE_JSON,
        )]),
        value => Err(format!(
            "Unknown sample effect bundle '{value}'. Expected 'circle'."
        )),
    }
}

fn sample_effect_requires_target(preset: &str) -> bool {
    matches!(
        preset.trim().to_ascii_lowercase().as_str(),
        "chase"
            | "front-dimmer-chase"
            | "front_dimmer_chase"
            | "spectrum"
            | "colour-spectrum"
            | "color-spectrum"
            | "colour-chase"
            | "color-chase"
            | "colour-mapping"
            | "color-mapping"
            | "circle"
            | "front-circle"
            | "front_circle"
            | "front-move-circle"
            | "front_move_circle"
    )
}

fn add_effect_preset_to_engine(
    engine: &EngineHandle,
    preset: EffectPreset,
    target_override: Option<&EffectTargetOverride>,
) -> Result<EffectId, String> {
    let snapshot = engine.snapshot();
    let effect_id = engine.allocate_effect_id();
    let enabled = preset.enabled;
    match preset.effect_type {
        EffectKind::Lfo => {
            let request = preset
                .lfo
                .ok_or_else(|| "LFO effect preset is missing its request body".to_string())?;
            let request = match target_override {
                Some(target_override) => {
                    let request = apply_lfo_effect_target_override(request, target_override);
                    validate_lfo_effect_request(&request)?;
                    request
                }
                None => request,
            };
            validate_effect_target_references(
                &snapshot,
                &request.fixture_ids,
                &request.video_targets,
            )?;
            engine
                .send(EngineCommand::AddLfoEffect { effect_id, request })
                .map_err(|error| error.to_string())?;
        }
        EffectKind::PositionWave => {
            let request = preset.position_wave.ok_or_else(|| {
                "Position wave effect preset is missing its request body".to_string()
            })?;
            let request = match target_override {
                Some(target_override) => {
                    let request =
                        apply_position_wave_effect_target_override(request, target_override);
                    validate_position_wave_effect_request(&request)?;
                    request
                }
                None => request,
            };
            validate_effect_target_references(
                &snapshot,
                &request.fixture_ids,
                &request.video_targets,
            )?;
            engine
                .send(EngineCommand::AddPositionWaveEffect { effect_id, request })
                .map_err(|error| error.to_string())?;
        }
        EffectKind::Color => {
            let request = preset
                .color
                .ok_or_else(|| "Color effect preset is missing its request body".to_string())?;
            let request = match target_override {
                Some(target_override) => {
                    let request = apply_color_effect_target_override(request, target_override)?;
                    validate_color_effect_request(&request)?;
                    request
                }
                None => request,
            };
            validate_effect_target_references(&snapshot, &request.fixture_ids, &[])?;
            engine.add_color_effect(effect_id, request, enabled)?;
        }
        EffectKind::Chaser => {
            let request = preset
                .chaser
                .ok_or_else(|| "Chaser effect preset is missing its request body".to_string())?;
            let request = match target_override {
                Some(target_override) => {
                    apply_chaser_effect_target_override(request, target_override, &snapshot)?
                }
                None => request,
            };
            validate_chaser_effect_request(&request)?;
            engine.add_chaser_effect(effect_id, request, enabled)?;
        }
        EffectKind::Move => {
            let request = preset
                .move_effect
                .ok_or_else(|| "Move effect preset is missing its request body".to_string())?;
            let request = match target_override {
                Some(target_override) => {
                    let request = apply_move_effect_target_override(request, target_override)?;
                    validate_move_effect_request(&request)?;
                    request
                }
                None => request,
            };
            validate_effect_target_references(&snapshot, &request.fixture_ids, &[])?;
            engine.add_move_effect(effect_id, request, enabled)?;
        }
        EffectKind::Value => {
            let request = preset
                .value
                .ok_or_else(|| "Value effect preset is missing its request body".to_string())?;
            let request = match target_override {
                Some(target_override) => {
                    apply_value_effect_target_override(request, target_override)
                }
                None => request,
            };
            validate_value_effect_request(&request)?;
            validate_effect_target_references(&snapshot, &request.fixture_ids, &[])?;
            engine.add_value_effect(effect_id, request, enabled)?;
        }
    }
    if !enabled
        && !matches!(
            preset.effect_type,
            EffectKind::Color | EffectKind::Chaser | EffectKind::Move | EffectKind::Value
        )
    {
        engine
            .send(EngineCommand::SetEffectEnabled {
                effect_id,
                enabled: false,
            })
            .map_err(|error| error.to_string())?;
    }
    Ok(effect_id)
}

fn add_sample_effect_preset_to_engine(
    engine: &EngineHandle,
    mut preset: EffectPreset,
    target_override: Option<&EffectTargetOverride>,
) -> Result<EffectId, String> {
    if preset.effect_type == EffectKind::Chaser {
        if let Some(target_override) = target_override {
            let request = preset
                .chaser
                .take()
                .ok_or_else(|| "Chaser effect preset is missing its request body".to_string())?;
            let snapshot = engine.snapshot();
            preset.chaser = Some(apply_fixture_index_chaser_effect_target_override(
                request,
                target_override,
                &snapshot,
            )?);
            return add_effect_preset_to_engine(engine, preset, None);
        }
    }
    add_effect_preset_to_engine(engine, preset, target_override)
}

#[tauri::command]
fn load_sample_effect_preset(
    state: State<'_, AppState>,
    preset: String,
    target_override: Option<EffectTargetOverride>,
) -> Result<EffectId, String> {
    if sample_effect_requires_target(&preset) && target_override.is_none() {
        return Err(format!(
            "Sample effect '{}' requires an explicit current target",
            preset.trim()
        ));
    }
    let (label, json) = sample_effect_preset_json(&preset)?;
    let preset: EffectPreset =
        serde_json::from_str(json).map_err(|error| format!("Failed to parse {label}: {error}"))?;
    validate_effect_preset(&preset)?;
    if let Some(target_override) = &target_override {
        validate_effect_target_override_for_preset(&preset, target_override)?;
    }
    add_sample_effect_preset_to_engine(&state.engine, preset, target_override.as_ref())
}

