fn phase1_smoke_first_8(snapshot: &EngineSnapshot) -> Vec<u8> {
    let preview = snapshot
        .dmx_previews
        .iter()
        .find(|candidate| candidate.universe == 0)
        .map(|candidate| candidate.values.as_slice())
        .unwrap_or(snapshot.dmx_preview.as_slice());
    let mut first_8 = preview.iter().copied().take(8).collect::<Vec<_>>();
    first_8.resize(8, 0);
    first_8
}

#[tauri::command]
fn run_phase1_smoke(state: State<'_, AppState>) -> Result<Phase1SmokeReport, String> {
    let result = load_project_from_json(
        &state,
        PHASE1_SAMPLE_PROJECT_JSON,
        PHASE1_SAMPLE_PROJECT_LABEL.to_string(),
        None,
    )?;
    let loaded = state.engine.snapshot();
    let cue = loaded
        .cues
        .first()
        .cloned()
        .ok_or_else(|| "Phase 1 sample has no cue to trigger".to_string())?;
    state
        .engine
        .send(EngineCommand::TriggerCue(cue.id))
        .map_err(|error| error.to_string())?;

    let mut snapshot = state.engine.snapshot();
    for _ in 0..30 {
        let first_8 = phase1_smoke_first_8(&snapshot);
        if snapshot.active_cue_id == Some(cue.id) && first_8 == PHASE1_SMOKE_EXPECTED_FIRST_8 {
            break;
        }
        std::thread::sleep(Duration::from_millis(25));
        snapshot = state.engine.snapshot();
    }

    let first_8 = phase1_smoke_first_8(&snapshot);
    let non_zero_first_8 = first_8.iter().filter(|value| **value != 0).count();
    let cue_video_layer = snapshot.video.layers.first().cloned();
    let video_layer_count = snapshot.video.layers.len();
    let video_layer_label = cue_video_layer.as_ref().map(|layer| layer.label.clone());
    let video_layer_playing = cue_video_layer
        .as_ref()
        .is_some_and(|layer| layer.state.playing);
    let video_layer_opacity = cue_video_layer.as_ref().map(|layer| layer.state.opacity);
    let timeline_event_count = snapshot.timeline.events.len();
    let timeline_automation_count = snapshot.timeline.automations.len();
    let timeline_video_automation_count = snapshot.timeline.video_automations.len();
    let timeline_duration_ms = snapshot.timeline.duration_ms;
    let dmx_output_count = snapshot.dmx_outputs.len();
    let enabled_dmx_output_count = snapshot
        .dmx_outputs
        .iter()
        .filter(|output| output.enabled)
        .count();
    let dmx_preview_universe_count = snapshot.dmx_previews.len();
    let primary_output = snapshot
        .dmx_outputs
        .iter()
        .find(|output| output.enabled)
        .or_else(|| snapshot.dmx_outputs.first())
        .unwrap_or(&snapshot.output);
    let primary_output_label = dmx_output_route_label(primary_output);

    let timeline_probe_ms = 2000;
    state
        .engine
        .send(EngineCommand::SeekTimeline(timeline_probe_ms))
        .map_err(|error| error.to_string())?;
    let mut probe_snapshot = state.engine.snapshot();
    for _ in 0..30 {
        if probe_snapshot.timeline.position_ms == timeline_probe_ms
            && phase1_smoke_first_8(&probe_snapshot).first() == Some(&128)
            && probe_snapshot
                .video
                .layers
                .first()
                .map(|layer| (0.49..=0.51).contains(&layer.state.opacity))
                == Some(true)
        {
            break;
        }
        std::thread::sleep(Duration::from_millis(25));
        probe_snapshot = state.engine.snapshot();
    }
    let timeline_probe_dimmer_byte = phase1_smoke_first_8(&probe_snapshot)
        .first()
        .copied()
        .unwrap_or(0);
    let timeline_probe_video_opacity = probe_snapshot
        .video
        .layers
        .first()
        .map(|layer| layer.state.opacity);

    let passed = snapshot.active_cue_id == Some(cue.id)
        && first_8 == PHASE1_SMOKE_EXPECTED_FIRST_8
        && timeline_event_count >= 2
        && timeline_automation_count >= 1
        && timeline_video_automation_count >= 1
        && timeline_duration_ms >= 4000
        && dmx_output_count >= 1
        && enabled_dmx_output_count >= 1
        && dmx_preview_universe_count >= 1
        && video_layer_count >= 1
        && video_layer_playing
        && video_layer_opacity.is_some_and(|opacity| (opacity - 1.0).abs() < 0.001)
        && timeline_probe_dimmer_byte == 128
        && timeline_probe_video_opacity.is_some_and(|opacity| (0.49..=0.51).contains(&opacity));
    Ok(Phase1SmokeReport {
        path: result.path,
        cue_id: cue.id,
        cue_label: cue.label,
        active_cue_id: snapshot.active_cue_id,
        timeline_event_count,
        timeline_automation_count,
        timeline_video_automation_count,
        timeline_duration_ms,
        timeline_probe_ms,
        timeline_probe_dimmer_byte,
        timeline_probe_video_opacity,
        dmx_output_count,
        enabled_dmx_output_count,
        dmx_preview_universe_count,
        primary_output_label,
        video_layer_count,
        video_layer_label,
        video_layer_playing,
        video_layer_opacity,
        first_8,
        expected_first_8: PHASE1_SMOKE_EXPECTED_FIRST_8.to_vec(),
        non_zero_first_8,
        passed,
    })
}

#[tauri::command]
fn take_open_project_paths(state: State<'_, AppState>) -> Result<Vec<String>, String> {
    let mut paths = state
        .pending_project_open_paths
        .lock()
        .map_err(|_| "Open project path queue lock was poisoned".to_string())?;
    Ok(std::mem::take(&mut *paths))
}

fn load_project_from_path(
    state: &State<'_, AppState>,
    path: &Path,
) -> Result<ProjectLoadResult, String> {
    let file_size = fs::metadata(path).map_err(|error| error.to_string())?.len();
    if file_size > PROJECT_FILE_MAX_BYTES {
        return Err(format!(
            "Project file is {file_size} bytes; the limit is {PROJECT_FILE_MAX_BYTES} bytes"
        ));
    }
    let json = fs::read_to_string(&path).map_err(|error| error.to_string())?;
    load_project_from_json(state, &json, path.to_string_lossy().to_string(), Some(path))
}

fn load_project_from_json(
    state: &State<'_, AppState>,
    json: &str,
    path_label: String,
    current_path: Option<&Path>,
) -> Result<ProjectLoadResult, String> {
    if json.len() as u64 > PROJECT_FILE_MAX_BYTES {
        return Err(format!(
            "Project JSON is {} bytes; the limit is {PROJECT_FILE_MAX_BYTES} bytes",
            json.len()
        ));
    }
    let project: ProjectFile = serde_json::from_str(&json).map_err(|error| error.to_string())?;
    load_project_from_file(state, project, path_label, current_path)
}

#[tauri::command]
fn load_project_checkpoint(
    state: State<'_, AppState>,
    project: ProjectFile,
    label: String,
    current_path: Option<String>,
) -> Result<ProjectLoadResult, String> {
    let current_path = current_path.map(PathBuf::from);
    if let Some(path) = current_path.as_deref() {
        if !is_syndocal_project_path(path) {
            return Err(format!(
                "Recovered Syndocal project path must use the .sdc extension: {}",
                path.to_string_lossy()
            ));
        }
    }
    load_project_from_file(&state, project, label, current_path.as_deref())
}

fn load_project_from_file(
    state: &State<'_, AppState>,
    mut project: ProjectFile,
    path_label: String,
    current_path: Option<&Path>,
) -> Result<ProjectLoadResult, String> {
    use_authored_video_snapshot(&mut project.snapshot);
    normalize_project_timeline_layers(&mut project.snapshot);
    validate_project_file(&project)?;
    let warnings = project_validation_warnings(&project);
    let profiles = project.custom_profiles.clone();
    {
        let mut custom_profiles = state
            .custom_profiles
            .lock()
            .map_err(|_| "Custom profile state lock was poisoned".to_string())?;
        custom_profiles.clear();
        for profile in &project.custom_profiles {
            custom_profiles.insert(profile.source_path.clone(), profile.clone());
        }
    }
    load_project_snapshot_with_runtime_reset(state, project.snapshot)?;
    reset_vj_preview_after_project_change(state);
    if let Some(path) = current_path {
        set_current_project_path(state, path)?;
    } else {
        clear_current_project_path(state)?;
    }
    Ok(ProjectLoadResult {
        path: path_label,
        profiles,
        warnings,
    })
}

fn load_project_snapshot_with_runtime_reset(
    state: &State<'_, AppState>,
    snapshot: EngineSnapshot,
) -> Result<(), String> {
    {
        let mut program_handoff = state
            .program_audio_handoff
            .state
            .lock()
            .map_err(|_| "Program audio handoff lock was poisoned".to_string())?;
        // Hold the coordinator lock while retiring the generation so the worker
        // cannot publish a fresh old-project job in the barrier gap.
        state.program_audio_handoff.invalidate_in_flight();
        program_handoff.suspended = true;
        program_handoff.pending_job = None;
    }
    let result = state
        .engine
        .load_project_snapshot(snapshot)
        .map_err(|error| error.to_string());
    if let Err(error) = result {
        let mut program_handoff = state
            .program_audio_handoff
            .state
            .lock()
            .map_err(|_| "Program audio handoff lock was poisoned".to_string())?;
        program_handoff.suspended = false;
        if program_handoff.config.enabled {
            if let Some(layer_id) = program_handoff
                .desired_layer_id
                .or(program_handoff.owned_layer_id)
            {
                if let Some(plan) = program_handoff.manual_take_plan(layer_id) {
                    state
                        .program_audio_handoff
                        .queue_locked(&mut program_handoff, ProgramAudioJobKind::Handoff(plan));
                }
            }
        }
        state.program_audio_handoff.wake.notify_all();
        return Err(error);
    }
    {
        let mut audio = state
            .media_audio
            .lock()
            .map_err(|_| "Media audio monitor lock was poisoned".to_string())?;
        audio.stop_all();
        audio.stop_all_timeline();
        audio.timeline_transport = TimelineAudioTransportState::default();
        audio.last_sync_error = None;
        audio.timeline_last_sync_error = None;
    }
    let published = state.engine.snapshot();
    let mut program_handoff = state
        .program_audio_handoff
        .state
        .lock()
        .map_err(|_| "Program audio handoff lock was poisoned".to_string())?;
    program_handoff.reset_for_project_change();
    program_handoff.suppress_through(published.video.auto_vj.status.last_action.as_ref());
    drop(program_handoff);
    state.program_audio_handoff.wake.notify_all();
    Ok(())
}

fn reset_vj_preview_after_project_change(state: &State<'_, AppState>) {
    if let Ok(mut transport) = state.vj_preview_transport.lock() {
        transport.clear_at(vj_preview_timestamp_ms());
    }
    let _ = reset_vj_preview_renderer(state);
}

fn normalize_project_save_path(mut path: PathBuf) -> Result<PathBuf, String> {
    if path.extension().is_none() {
        path.set_extension("sdc");
        return Ok(path);
    }
    if is_syndocal_project_path(&path) {
        Ok(path)
    } else {
        Err(format!(
            "Syndocal project files must use the .sdc extension: {}",
            path.to_string_lossy()
        ))
    }
}

fn is_user_template_path(path: &Path) -> bool {
    path.extension()
        .and_then(OsStr::to_str)
        .is_some_and(|extension| extension.eq_ignore_ascii_case("sdctemplate"))
}

fn normalize_user_template_save_path(mut path: PathBuf) -> Result<PathBuf, String> {
    if path.extension().is_none() {
        path.set_extension("sdctemplate");
        return Ok(path);
    }
    if is_user_template_path(&path) {
        Ok(path)
    } else {
        Err(format!(
            "Syndocal user templates must use the .sdctemplate extension: {}",
            path.to_string_lossy()
        ))
    }
}

fn validate_user_template_open_path(path: &Path) -> Result<(), String> {
    if is_user_template_path(path) {
        Ok(())
    } else {
        Err(format!(
            "Syndocal user templates must use the .sdctemplate extension: {}",
            path.to_string_lossy()
        ))
    }
}

fn normalize_user_template_file(
    mut template: UserTemplateFile,
) -> Result<UserTemplateFile, String> {
    if template.version != USER_TEMPLATE_VERSION {
        return Err(format!(
            "Unsupported Syndocal user template version {}",
            template.version
        ));
    }
    validate_app_name("user template", &template.app)?;
    template.label = template.label.trim().to_string();
    if template.label.is_empty() || template.label.chars().count() > 80 {
        return Err("User template label must contain 1 to 80 characters".to_string());
    }
    validate_project_file(&template.project)?;
    template.midi_mappings = validate_midi_control_mappings(template.midi_mappings)?;
    template.osc_mappings = validate_osc_control_mappings(template.osc_mappings)?;
    Ok(template)
}

fn validate_project_open_path(path: &Path) -> Result<(), String> {
    if !is_syndocal_project_path(path) {
        return Err(format!(
            "Syndocal project files must use the .sdc extension: {}",
            path.to_string_lossy()
        ));
    }
    if !path.is_file() {
        return Err(format!(
            "Project file was not found: {}",
            path.to_string_lossy()
        ));
    }
    Ok(())
}

