fn startup_project_path_from_args(args: impl IntoIterator<Item = OsString>) -> Option<PathBuf> {
    project_paths_from_args(args, None).into_iter().next()
}

fn project_paths_from_single_instance_args(args: Vec<String>, cwd: &str) -> Vec<String> {
    let cwd_path = (!cwd.trim().is_empty()).then(|| PathBuf::from(cwd));
    project_paths_from_args(args.into_iter().map(OsString::from), cwd_path.as_deref())
        .into_iter()
        .map(|path| path.to_string_lossy().to_string())
        .collect()
}

fn project_paths_from_args(
    args: impl IntoIterator<Item = OsString>,
    cwd: Option<&Path>,
) -> Vec<PathBuf> {
    args.into_iter()
        .skip(1)
        .map(PathBuf::from)
        .map(|path| resolve_project_arg_path(path, cwd))
        .filter(|path| is_syndocal_project_path(path))
        .collect()
}

fn resolve_project_arg_path(path: PathBuf, cwd: Option<&Path>) -> PathBuf {
    if path.is_absolute() {
        path
    } else if let Some(cwd) = cwd {
        cwd.join(path)
    } else {
        path
    }
}

fn is_syndocal_project_path(path: &Path) -> bool {
    has_extension(path, "sdc")
}

fn has_extension(path: &Path, expected: &str) -> bool {
    path.extension()
        .and_then(OsStr::to_str)
        .is_some_and(|extension| extension.eq_ignore_ascii_case(expected))
}

fn validate_touch_surface(
    surface: &TouchSurfaceSummary,
    snapshot: &EngineSnapshot,
) -> Result<(), String> {
    const TOUCH_GRID_COLUMNS: u16 = 12;
    const TOUCH_GRID_ROWS: u16 = 8;
    if surface.pages.len() > 64 {
        return Err("Touch surface contains more than 64 pages".to_string());
    }
    let mut page_ids = HashSet::new();
    let mut control_ids = HashSet::new();
    for page in &surface.pages {
        if page.id == 0 || !page_ids.insert(page.id) {
            return Err(format!(
                "Touch page {} has an invalid or duplicate ID",
                page.id
            ));
        }
        if page.label.trim().is_empty() || page.label.chars().count() > 64 {
            return Err(format!("Touch page {} has an invalid label", page.id));
        }
        if page.controls.len() > 256 {
            return Err(format!(
                "Touch page {} contains more than 256 controls",
                page.id
            ));
        }
        for control in &page.controls {
            if control.id == 0 || !control_ids.insert(control.id) {
                return Err(format!(
                    "Touch control {} has an invalid or duplicate ID",
                    control.id
                ));
            }
            if control.label.trim().is_empty() || control.label.chars().count() > 128 {
                return Err(format!("Touch control {} has an invalid label", control.id));
            }
            if control.w == 0
                || control.h == 0
                || control.x.saturating_add(control.w) > TOUCH_GRID_COLUMNS
                || control.y.saturating_add(control.h) > TOUCH_GRID_ROWS
            {
                return Err(format!(
                    "Touch control {} is outside the 12x8 surface grid",
                    control.id
                ));
            }
            let Some(binding) = &control.binding else {
                continue;
            };
            match binding {
                TouchControlBinding::FixtureAttribute {
                    fixture_id,
                    attribute,
                } => {
                    let fixture = snapshot
                        .fixtures
                        .iter()
                        .find(|fixture| fixture.id == *fixture_id)
                        .ok_or_else(|| {
                            format!(
                                "Touch control {} references missing fixture {}",
                                control.id, fixture_id
                            )
                        })?;
                    if !fixture
                        .controls
                        .iter()
                        .any(|candidate| candidate.attribute == *attribute)
                    {
                        return Err(format!(
                            "Touch control {} references missing fixture attribute '{}'",
                            control.id, attribute
                        ));
                    }
                }
                TouchControlBinding::GroupAttribute {
                    group_id,
                    attribute,
                } => {
                    if !snapshot.fixtures.iter().any(|fixture| {
                        fixture.group_ids.contains(group_id)
                            && fixture
                                .controls
                                .iter()
                                .any(|candidate| candidate.attribute == *attribute)
                    }) {
                        return Err(format!(
                            "Touch control {} references missing group attribute '{} / {}'",
                            control.id, group_id, attribute
                        ));
                    }
                }
                TouchControlBinding::FixtureColor { fixture_id } => {
                    if !snapshot.fixtures.iter().any(|fixture| {
                        fixture.id == *fixture_id && fixture_supports_color_effect(fixture)
                    }) {
                        return Err(format!(
                            "Touch control {} references fixture {} without color controls",
                            control.id, fixture_id
                        ));
                    }
                }
                TouchControlBinding::GroupColor { group_id } => {
                    if !snapshot.fixtures.iter().any(|fixture| {
                        fixture.group_ids.contains(group_id)
                            && fixture_supports_color_effect(fixture)
                    }) {
                        return Err(format!(
                            "Touch control {} references group '{}' without color controls",
                            control.id, group_id
                        ));
                    }
                }
                TouchControlBinding::FixturePanTilt {
                    fixture_id,
                    pan_attribute,
                    tilt_attribute,
                } => {
                    let fixture = snapshot
                        .fixtures
                        .iter()
                        .find(|fixture| fixture.id == *fixture_id)
                        .ok_or_else(|| {
                            format!(
                                "Touch control {} references missing fixture {}",
                                control.id, fixture_id
                            )
                        })?;
                    if ![pan_attribute, tilt_attribute]
                        .into_iter()
                        .all(|attribute| {
                            fixture
                                .controls
                                .iter()
                                .any(|control| control.attribute == attribute.as_str())
                        })
                    {
                        return Err(format!(
                            "Touch control {} references missing Pan/Tilt attributes",
                            control.id
                        ));
                    }
                }
                TouchControlBinding::GroupPanTilt {
                    group_id,
                    pan_attribute,
                    tilt_attribute,
                } => {
                    if !snapshot.fixtures.iter().any(|fixture| {
                        fixture.group_ids.contains(group_id)
                            && [pan_attribute, tilt_attribute]
                                .into_iter()
                                .all(|attribute| {
                                    fixture
                                        .controls
                                        .iter()
                                        .any(|control| control.attribute == attribute.as_str())
                                })
                    }) {
                        return Err(format!(
                            "Touch control {} references missing group Pan/Tilt target",
                            control.id
                        ));
                    }
                }
                TouchControlBinding::Cue { cue_id } => {
                    if !snapshot.cues.iter().any(|cue| cue.id == *cue_id) {
                        return Err(format!(
                            "Touch control {} references missing cue {}",
                            control.id, cue_id
                        ));
                    }
                }
                TouchControlBinding::GroupSubmaster { group_id } => {
                    if !snapshot
                        .fixtures
                        .iter()
                        .any(|fixture| fixture.group_ids.contains(group_id))
                    {
                        return Err(format!(
                            "Touch control {} references missing submaster group '{}'",
                            control.id, group_id
                        ));
                    }
                }
                TouchControlBinding::SelectedFixtureAttribute { attribute }
                    if attribute.trim().is_empty() =>
                {
                    return Err(format!(
                        "Touch control {} requires a selected-fixture attribute",
                        control.id
                    ));
                }
                TouchControlBinding::SelectedFixturePanTilt {
                    pan_attribute,
                    tilt_attribute,
                } if pan_attribute.trim().is_empty() || tilt_attribute.trim().is_empty() => {
                    return Err(format!(
                        "Touch control {} requires Pan and Tilt attributes",
                        control.id
                    ));
                }
                _ => {}
            }
        }
    }
    Ok(())
}

fn validate_project_file(project: &ProjectFile) -> Result<(), String> {
    if project.version != PROJECT_FILE_VERSION {
        return Err(format!("Unsupported project version {}", project.version));
    }
    validate_app_name("project", &project.app)?;
    validate_project_custom_profiles(&project.custom_profiles)?;
    validate_touch_surface(&project.snapshot.touch_surface, &project.snapshot)?;
    validate_unique_ids(
        "fixture",
        project.snapshot.fixtures.iter().map(|fixture| fixture.id),
    )?;
    validate_unique_ids("cue", project.snapshot.cues.iter().map(|cue| cue.id))?;
    validate_unique_ids(
        "cue list",
        project
            .snapshot
            .cue_lists
            .iter()
            .map(|cue_list| cue_list.id),
    )?;
    validate_unique_ids(
        "palette",
        project.snapshot.palettes.iter().map(|palette| palette.id),
    )?;
    if project.snapshot.palettes.len() > 128 {
        return Err("Project contains more than 128 reference palettes".to_string());
    }
    for palette in &project.snapshot.palettes {
        if palette.id == 0 || palette.label.trim().is_empty() {
            return Err(format!(
                "Project palette {} has an invalid ID or label",
                palette.id
            ));
        }
        let mut values = palette.values.clone();
        validate_reference_palette_values(&mut values).map_err(|error| {
            format!(
                "Project palette {} '{}' is invalid: {error}",
                palette.id, palette.label
            )
        })?;
    }
    validate_unique_ids(
        "playback executor",
        project
            .snapshot
            .playback_executors
            .iter()
            .map(|executor| executor.id),
    )?;
    if project.snapshot.playback_executors.len() > 64 {
        return Err("Project contains more than 64 playback executors".to_string());
    }
    if !project.snapshot.playback_master.is_finite()
        || !(0.0..=1.0).contains(&project.snapshot.playback_master)
    {
        return Err("Project Playback Master must be from 0 to 1".to_string());
    }
    let mut executor_slots = HashSet::new();
    for executor in &project.snapshot.playback_executors {
        if executor.id == 0
            || executor.label.trim().is_empty()
            || executor.page == 0
            || executor.page > 99
            || executor.slot == 0
            || executor.slot > 16
            || !executor.level.is_finite()
            || !(0.0..=1.0).contains(&executor.level)
        {
            return Err(format!(
                "Project Playback Executor {} has invalid metadata",
                executor.id
            ));
        }
        if !project
            .snapshot
            .cue_lists
            .iter()
            .any(|cue_list| cue_list.id == executor.cue_list_id)
        {
            return Err(format!(
                "Project Playback Executor {} references missing Cue List {}",
                executor.id, executor.cue_list_id
            ));
        }
        if !executor_slots.insert((executor.page, executor.slot)) {
            return Err(format!(
                "Project contains duplicate Playback Executor page {} slot {}",
                executor.page, executor.slot
            ));
        }
    }
    if !project
        .snapshot
        .cue_lists
        .iter()
        .any(|cue_list| cue_list.id == protocol::DEFAULT_CUE_LIST_ID)
    {
        return Err("Project is missing the Main Cue List".to_string());
    }
    for cue_list in &project.snapshot.cue_lists {
        if cue_list.id == 0 || cue_list.label.trim().is_empty() {
            return Err(format!(
                "Project Cue List {} has an invalid ID or label",
                cue_list.id
            ));
        }
        if let Some(active_cue_id) = cue_list.active_cue_id {
            if !project
                .snapshot
                .cues
                .iter()
                .any(|cue| cue.id == active_cue_id && cue.cue_list_id == cue_list.id)
            {
                return Err(format!(
                    "Project Cue List {} references missing active cue {}",
                    cue_list.id, active_cue_id
                ));
            }
        }
    }
    for cue in &project.snapshot.cues {
        if !project
            .snapshot
            .cue_lists
            .iter()
            .any(|cue_list| cue_list.id == cue.cue_list_id)
        {
            return Err(format!(
                "Project cue {} references missing Cue List {}",
                cue.id, cue.cue_list_id
            ));
        }
        validate_cue_authored_beats(cue.authored_beats).map_err(|error| {
            format!(
                "Project cue {} '{}' has invalid authored length: {error}",
                cue.id, cue.label
            )
        })?;
    }
    validate_unique_ids(
        "timeline event",
        project
            .snapshot
            .timeline
            .events
            .iter()
            .map(|event| event.id),
    )?;
    validate_unique_ids(
        "timeline layer",
        project
            .snapshot
            .timeline
            .layers
            .iter()
            .map(|layer| u64::from(layer.id)),
    )?;
    for layer in &project.snapshot.timeline.layers {
        if layer.label.trim().is_empty() {
            return Err(format!(
                "Project timeline layer {} has an empty label",
                layer.id
            ));
        }
    }
    validate_unique_ids(
        "timeline audio clip",
        project
            .snapshot
            .timeline
            .audio_clips
            .iter()
            .map(|clip| clip.id),
    )?;
    validate_project_timeline_audio_clips(&project.snapshot)?;
    validate_project_timeline_scene_blocks(&project.snapshot)?;
    validate_unique_ids(
        "timeline automation",
        project
            .snapshot
            .timeline
            .automations
            .iter()
            .map(|automation| automation.id),
    )?;
    validate_unique_ids(
        "timeline video automation",
        project
            .snapshot
            .timeline
            .video_automations
            .iter()
            .map(|automation| automation.id),
    )?;
    validate_unique_ids(
        "video layer",
        project.snapshot.video.layers.iter().map(|layer| layer.id),
    )?;
    validate_unique_ids(
        "video composition",
        project
            .snapshot
            .video
            .compositions
            .iter()
            .map(|composition| composition.id),
    )?;
    validate_unique_ids(
        "video output",
        project
            .snapshot
            .video
            .outputs
            .iter()
            .map(|output| output.id),
    )?;
    validate_unique_ids(
        "effect",
        project.snapshot.effects.iter().map(|effect| effect.id),
    )?;
    validate_unique_ids(
        "node graph",
        project.snapshot.node_graphs.iter().map(|graph| graph.id),
    )?;
    validate_project_fixture_patches(&project.snapshot.fixtures)?;
    validate_project_fixture_geometries(&project.snapshot.fixtures)?;
    validate_project_fixture_attribute_values(&project.snapshot.fixtures)?;
    validate_project_dmx_outputs(&project.snapshot)?;
    validate_stage_map_config(&project.snapshot.stage_map)?;
    validate_project_stage_map_presets(&project.snapshot.stage_map_presets)?;
    validate_project_stage_objects(&project.snapshot.stage_objects)?;
    validate_project_custom_profile_refs(&project.snapshot, &project.custom_profiles)?;
    validate_project_lighting_references(&project.snapshot)?;
    validate_project_video_graph(&project.snapshot)?;
    validate_project_node_graphs(&project.snapshot)?;
    Ok(())
}

fn project_validation_warnings(project: &ProjectFile) -> Vec<String> {
    let mut warnings = project
        .snapshot
        .cues
        .iter()
        .filter_map(|cue| {
            let group_id = cue.group_id.as_deref()?;
            let carried = project.snapshot.fixtures.iter().any(|fixture| {
                fixture
                    .group_ids
                    .iter()
                    .any(|fixture_group_id| group_matches(fixture_group_id, group_id))
            });
            (!carried).then(|| {
                format!(
                    "Cue {} '{}' references fixture group '{group_id}', but no fixture carries that group",
                    cue.cue_number, cue.label
                )
            })
        })
        .collect::<Vec<_>>();
    warnings.extend(
        project
            .snapshot
            .timeline
            .audio_clips
            .iter()
            .filter(|clip| !clip.path.trim().is_empty() && !Path::new(&clip.path).exists())
            .map(|clip| {
                format!(
                    "Timeline audio clip {} file '{}' is unavailable; the show remains loadable for travel",
                    clip.id, clip.path
                )
            }),
    );
    warnings
}

fn validate_unique_ids(label: &str, ids: impl IntoIterator<Item = u64>) -> Result<(), String> {
    let mut seen = HashSet::new();
    for id in ids {
        if !seen.insert(id) {
            return Err(format!("Project contains duplicate {label} id {id}"));
        }
    }
    Ok(())
}

fn validate_project_timeline_audio_clips(snapshot: &EngineSnapshot) -> Result<(), String> {
    for clip in &snapshot.timeline.audio_clips {
        if clip.path.trim().is_empty() {
            return Err(format!(
                "Project timeline audio clip {} has an empty path",
                clip.id
            ));
        }
        if clip.duration_ms == 0 {
            return Err(format!(
                "Project timeline audio clip {} has zero duration",
                clip.id
            ));
        }
        if !clip.gain.is_finite() || !(0.0..=2.0).contains(&clip.gain) {
            return Err(format!(
                "Project timeline audio clip {} gain must be from 0 to 2",
                clip.id
            ));
        }
        if clip.fade_in_ms.saturating_add(clip.fade_out_ms) > clip.duration_ms {
            return Err(format!(
                "Project timeline audio clip {} fade windows exceed its duration",
                clip.id
            ));
        }
        let layer = snapshot
            .timeline
            .layers
            .iter()
            .find(|layer| layer.id == clip.layer_id)
            .ok_or_else(|| {
                format!(
                    "Project timeline audio clip {} references missing layer {}",
                    clip.id, clip.layer_id
                )
            })?;
        if !matches!(layer.kind, TimelineLayerKind::Audio) {
            return Err(format!(
                "Project timeline audio clip {} references non-Audio layer {}",
                clip.id, clip.layer_id
            ));
        }
    }
    Ok(())
}

fn validate_project_timeline_scene_blocks(snapshot: &EngineSnapshot) -> Result<(), String> {
    for event in &snapshot.timeline.events {
        let Some(cue) = snapshot.cues.iter().find(|cue| cue.id == event.cue_id) else {
            return Err(format!(
                "Project timeline event {} references missing cue {}",
                event.id, event.cue_id
            ));
        };
        if let Some(layer_id) = event.layer_id {
            let Some(layer) = snapshot
                .timeline
                .layers
                .iter()
                .find(|layer| layer.id == layer_id)
            else {
                return Err(format!(
                    "Project timeline event {} references missing timeline layer {layer_id}",
                    event.id
                ));
            };
            let expected_track = match layer.kind {
                TimelineLayerKind::Lighting => TimelineTrackKind::Lighting,
                TimelineLayerKind::Video => TimelineTrackKind::Video,
                TimelineLayerKind::Audio => {
                    return Err(format!(
                        "Project timeline event {} references Audio timeline layer {layer_id}; cue events can only target Lighting or Video layers",
                        event.id
                    ));
                }
            };
            if event.track != expected_track {
                return Err(format!(
                    "Project timeline event {} uses legacy track {:?}, but timeline layer {layer_id} is {:?}; update the event track to {:?}",
                    event.id, event.track, layer.kind, expected_track
                ));
            }
        } else if !snapshot.timeline.layers.is_empty() {
            let legacy_kind = TimelineLayerKind::from(&event.track);
            if !snapshot
                .timeline
                .layers
                .iter()
                .any(|layer| layer.kind == legacy_kind)
            {
                return Err(format!(
                    "Project timeline event {} has no layer_id and no {:?} timeline layer exists for its legacy track",
                    event.id, legacy_kind
                ));
            }
        }
        validate_timeline_scene_block_fields(
            &snapshot.timeline.events,
            &format!("Project timeline event {}", event.id),
            event.time_ms,
            event.time_beats,
            event.duration_ms,
            event.duration_beats,
            event.conform_to_tempo,
            event.loop_fill,
            event.loop_count,
            event.jump_to_event_id,
            true,
            cue.authored_beats,
        )?;
    }
    Ok(())
}

fn validate_project_fixture_patches(fixtures: &[PatchedFixtureSummary]) -> Result<(), String> {
    let mut occupied = Vec::new();
    for fixture in fixtures {
        if fixture.label.trim().is_empty() {
            return Err(format!(
                "Project fixture {} has an empty fixture label",
                fixture.id
            ));
        }
        validate_fixture_transform(&fixture.position, &fixture.rotation).map_err(|error| {
            format!(
                "Project fixture {} '{}' has invalid transform: {error}",
                fixture.id, fixture.label
            )
        })?;
        validate_group_ids(&fixture.group_ids).map_err(|error| {
            format!(
                "Project fixture {} '{}' has invalid group id: {error}",
                fixture.id, fixture.label
            )
        })?;
        if fixture.address == 0 || fixture.address > 512 {
            return Err(format!(
                "Project fixture {} '{}' has invalid DMX address {}",
                fixture.id, fixture.label, fixture.address
            ));
        }
        let footprint = fixture_controls_footprint(&fixture.controls).ok_or_else(|| {
            format!(
                "Project fixture {} '{}' has no DMX channel offsets",
                fixture.id, fixture.label
            )
        })?;
        let range = dmx_range(fixture.address, footprint).ok_or_else(|| {
            format!(
                "Project fixture {} '{}' has no DMX channel offsets",
                fixture.id, fixture.label
            )
        })?;
        if range.1 > 512 {
            return Err(format!(
                "Project fixture {} '{}' exceeds DMX universe {}: start {}, footprint {}ch, end {}",
                fixture.id, fixture.label, fixture.universe, fixture.address, footprint, range.1
            ));
        }
        for (occupied_universe, occupied_range, occupied_label) in &occupied {
            if *occupied_universe == fixture.universe && ranges_overlap(range, *occupied_range) {
                return Err(format!(
                    "Project fixture {} '{}' conflicts in universe {}: {}-{} overlaps {} at {}-{}",
                    fixture.id,
                    fixture.label,
                    fixture.universe,
                    range.0,
                    range.1,
                    occupied_label,
                    occupied_range.0,
                    occupied_range.1
                ));
            }
        }
        occupied.push((
            fixture.universe,
            range,
            format!("fixture {} '{}'", fixture.id, fixture.label),
        ));
    }
    Ok(())
}

fn validate_project_fixture_geometries(fixtures: &[PatchedFixtureSummary]) -> Result<(), String> {
    for fixture in fixtures {
        validate_geometry_collection(
            &format!("fixture {} '{}'", fixture.id, fixture.label),
            &fixture.geometries,
            &fixture.controls,
        )?;
    }
    Ok(())
}

fn validate_geometry_collection(
    owner_label: &str,
    geometries: &[GeometrySummary],
    controls: &[AttributeControl],
) -> Result<(), String> {
    let mut geometry_names = HashSet::new();
    let mut parents_by_name = HashMap::new();

    for geometry in geometries {
        let name = geometry.name.trim();
        if name.is_empty() {
            return Err(format!(
                "Project {owner_label} has a geometry node with an empty name"
            ));
        }
        if !geometry_names.insert(name.to_string()) {
            return Err(format!(
                "Project {owner_label} contains duplicate geometry node '{name}'"
            ));
        }
        if geometry.kind.trim().is_empty() {
            return Err(format!(
                "Project {owner_label} geometry '{name}' has an empty kind"
            ));
        }
        if geometry.matrix.iter().any(|value| !value.is_finite()) {
            return Err(format!(
                "Project {owner_label} geometry '{name}' has a non-finite transform matrix"
            ));
        }
        let parent = geometry
            .parent
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty());
        if let Some(parent) = parent {
            if parent == name {
                return Err(format!(
                    "Project {owner_label} geometry '{name}' cannot parent itself"
                ));
            }
            parents_by_name.insert(name.to_string(), parent.to_string());
        }
        if let Some(dimensions) = geometry.model_dimensions {
            if !dimensions.x.is_finite()
                || !dimensions.y.is_finite()
                || !dimensions.z.is_finite()
                || dimensions.x < 0.0
                || dimensions.y < 0.0
                || dimensions.z < 0.0
            {
                return Err(format!(
                    "Project {owner_label} geometry '{name}' has invalid model dimensions"
                ));
            }
        }
        for (label, value) in [
            ("beam angle", geometry.beam_angle_deg),
            ("field angle", geometry.field_angle_deg),
            ("beam radius", geometry.beam_radius),
        ] {
            if let Some(value) = value {
                if !value.is_finite() || value < 0.0 {
                    return Err(format!(
                        "Project {owner_label} geometry '{name}' has invalid {label}"
                    ));
                }
            }
        }
    }

    for (name, parent) in &parents_by_name {
        if !geometry_names.contains(parent) {
            return Err(format!(
                "Project {owner_label} geometry '{name}' references missing parent '{parent}'"
            ));
        }
    }

    for geometry in geometries {
        let mut seen = HashSet::new();
        let mut current = geometry.name.trim().to_string();
        while let Some(parent) = parents_by_name.get(&current) {
            if !seen.insert(current.clone()) {
                return Err(format!(
                    "Project {owner_label} geometry '{}' contains a parent cycle",
                    geometry.name
                ));
            }
            current = parent.clone();
        }
    }

    for control in controls {
        let Some(geometry_name) = control
            .geometry
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            continue;
        };
        if !geometry_names.contains(geometry_name) {
            return Err(format!(
                "Project {owner_label} control '{}' references missing geometry '{geometry_name}'",
                control.attribute
            ));
        }
    }

    Ok(())
}

fn validate_project_fixture_attribute_values(
    fixtures: &[PatchedFixtureSummary],
) -> Result<(), String> {
    for fixture in fixtures {
        let valid_attributes = fixture
            .controls
            .iter()
            .map(|control| control.attribute.as_str())
            .collect::<HashSet<_>>();
        let mut seen_attributes = HashSet::new();
        for value in &fixture.attribute_values {
            if !seen_attributes.insert(value.attribute.as_str()) {
                return Err(format!(
                    "Project fixture {} '{}' contains duplicate attribute value '{}'",
                    fixture.id, fixture.label, value.attribute
                ));
            }
            if !valid_attributes.contains(value.attribute.as_str()) {
                return Err(format!(
                    "Project fixture {} '{}' has saved value for unavailable attribute '{}'",
                    fixture.id, fixture.label, value.attribute
                ));
            }
        }
    }
    Ok(())
}

fn validate_project_dmx_outputs(snapshot: &EngineSnapshot) -> Result<(), String> {
    if snapshot.dmx_outputs.is_empty() {
        validate_dmx_output_routes(std::slice::from_ref(&snapshot.output))
    } else {
        validate_dmx_output_routes(&snapshot.dmx_outputs)
    }
}

fn validate_project_cue_effect_params(
    snapshot: &EngineSnapshot,
    fixtures_by_id: &HashMap<FixtureId, &PatchedFixtureSummary>,
    cue_id: CueId,
    effect_id: EffectId,
    params: &EffectParamsSnapshot,
) -> Result<(), String> {
    let owner_label = format!("cue {cue_id} owned effect {effect_id}");
    validate_effect_params_snapshot(params)
        .map_err(|error| format!("Project {owner_label} is invalid: {error}"))?;

    let validate_video_targets = |targets: &[VideoEffectTarget]| -> Result<(), String> {
        let layer_ids = snapshot
            .video
            .layers
            .iter()
            .map(|layer| layer.id)
            .collect::<HashSet<_>>();
        for target in targets {
            for layer_id in &target.layer_ids {
                validate_project_video_layer_ref(
                    &layer_ids,
                    *layer_id,
                    &format!("cue {cue_id} owned effect"),
                    effect_id,
                )?;
            }
        }
        Ok(())
    };

    match params {
        EffectParamsSnapshot::Lfo(request) => {
            validate_project_effect_fixture_targets(
                snapshot,
                fixtures_by_id,
                &request.fixture_ids,
                &request.target_group_ids,
                &request.attribute,
                &owner_label,
            )?;
            validate_video_targets(&request.video_targets)
        }
        EffectParamsSnapshot::PositionWave(request) => {
            validate_project_effect_fixture_targets(
                snapshot,
                fixtures_by_id,
                &request.fixture_ids,
                &request.target_group_ids,
                &request.attribute,
                &owner_label,
            )?;
            validate_video_targets(&request.video_targets)
        }
        EffectParamsSnapshot::Color(request) => validate_project_color_effect_targets(
            snapshot,
            fixtures_by_id,
            &request.fixture_ids,
            &request.target_group_ids,
            &owner_label,
        ),
        EffectParamsSnapshot::Chaser(request) => {
            validate_project_chaser_effect_targets(
                snapshot,
                fixtures_by_id,
                request,
                &owner_label,
            )?;
            Ok(())
        }
        EffectParamsSnapshot::Move(request) => validate_project_move_effect_targets(
            snapshot,
            fixtures_by_id,
            &request.fixture_ids,
            &request.target_group_ids,
            &owner_label,
        ),
        EffectParamsSnapshot::Value(request) => validate_project_effect_fixture_targets(
            snapshot,
            fixtures_by_id,
            &request.fixture_ids,
            &request.target_group_ids,
            &request.attribute,
            &owner_label,
        ),
    }
}

fn validate_project_lighting_references(snapshot: &EngineSnapshot) -> Result<(), String> {
    let fixtures_by_id = snapshot
        .fixtures
        .iter()
        .map(|fixture| (fixture.id, fixture))
        .collect::<HashMap<_, _>>();
    let palette_ids = snapshot
        .palettes
        .iter()
        .map(|palette| palette.id)
        .collect::<HashSet<_>>();
    let effect_ids = snapshot
        .effects
        .iter()
        .map(|effect| effect.id)
        .collect::<HashSet<_>>();

    for cue in &snapshot.cues {
        if cue.label.trim().is_empty() {
            return Err(format!("Project cue {} has an empty label", cue.id));
        }
        validate_cue_parts_for_summary(cue, &cue.parts)?;
        validate_cue_mib_fixture_ids(cue, &cue.mib_fixture_ids)?;
        validate_project_unique_refs(
            &format!("cue {} fixture target", cue.id),
            &cue.targets
                .iter()
                .map(|target| target.fixture_id)
                .collect::<Vec<_>>(),
        )?;
        for target in &cue.targets {
            validate_project_fixture_attribute_values_for_target(
                &fixtures_by_id,
                target.fixture_id,
                &target.values,
                &format!("cue {}", cue.id),
            )?;
        }
        let mut step_duration_ms = 0_u64;
        for (step_index, step) in cue.steps.iter().enumerate() {
            step_duration_ms = step_duration_ms
                .checked_add(step.fade_ms)
                .and_then(|value| value.checked_add(step.hold_ms))
                .ok_or_else(|| {
                    format!(
                        "Project cue {} step {} duration exceeds the supported range",
                        cue.id,
                        step_index + 1
                    )
                })?;
            validate_project_unique_refs(
                &format!("cue {} step {} fixture target", cue.id, step_index + 1),
                &step
                    .values
                    .iter()
                    .map(|target| target.fixture_id)
                    .collect::<Vec<_>>(),
            )?;
            for target in &step.values {
                validate_project_fixture_attribute_values_for_target(
                    &fixtures_by_id,
                    target.fixture_id,
                    &target.values,
                    &format!("cue {} step {}", cue.id, step_index + 1),
                )?;
            }
        }
        validate_project_unique_refs(
            &format!("cue {} palette", cue.id),
            &cue.palette_targets
                .iter()
                .map(|target| target.palette_id)
                .collect::<Vec<_>>(),
        )?;
        for target in &cue.palette_targets {
            if !palette_ids.contains(&target.palette_id) {
                return Err(format!(
                    "Project cue {} references missing palette {}",
                    cue.id, target.palette_id
                ));
            }
            if target.fixture_ids.is_empty() {
                return Err(format!(
                    "Project cue {} palette {} has no fixture targets",
                    cue.id, target.palette_id
                ));
            }
            validate_project_unique_refs(
                &format!("cue {} palette {} fixture", cue.id, target.palette_id),
                &target.fixture_ids,
            )?;
            for fixture_id in &target.fixture_ids {
                if !fixtures_by_id.contains_key(fixture_id) {
                    return Err(format!(
                        "Project cue {} palette {} references missing fixture {}",
                        cue.id, target.palette_id, fixture_id
                    ));
                }
            }
        }
        validate_project_unique_refs(
            &format!("cue {} effect", cue.id),
            &cue.effect_targets
                .iter()
                .map(|target| target.effect_id)
                .collect::<Vec<_>>(),
        )?;
        for target in &cue.effect_targets {
            if let Some(params) = &target.params {
                validate_project_cue_effect_params(
                    snapshot,
                    &fixtures_by_id,
                    cue.id,
                    target.effect_id,
                    params,
                )?;
            } else if !effect_ids.contains(&target.effect_id) {
                return Err(format!(
                    "Project cue {} references missing effect {}",
                    cue.id, target.effect_id
                ));
            }
        }
    }

    for value in &snapshot.programmer.values {
        validate_project_fixture_attribute_values_for_target(
            &fixtures_by_id,
            value.fixture_id,
            &[protocol::AttributeValueSummary {
                attribute: value.attribute.clone(),
                value: value.value,
            }],
            "programmer",
        )?;
    }

    for event in &snapshot.timeline.events {
        if !snapshot.cues.iter().any(|cue| cue.id == event.cue_id) {
            return Err(format!(
                "Project timeline event {} references missing cue {}",
                event.id, event.cue_id
            ));
        }
    }

    for automation in &snapshot.timeline.automations {
        validate_project_fixture_attribute_ref(
            &fixtures_by_id,
            automation.fixture_id,
            &automation.attribute,
            &format!("timeline automation {}", automation.id),
        )?;
        if automation.keyframes.is_empty() {
            return Err(format!(
                "Project timeline automation {} requires at least one keyframe",
                automation.id
            ));
        }
        validate_project_lighting_keyframes(
            &automation.keyframes,
            &format!("timeline automation {}", automation.id),
        )?;
    }

    for effect in &snapshot.effects {
        validate_project_effect_body(effect)?;
        if matches!(effect.effect_type, EffectKind::Color) {
            let request = effect.color.as_ref().ok_or_else(|| {
                format!(
                    "Project effect {} is missing its Color request body",
                    effect.id
                )
            })?;
            if !effect.video_targets.is_empty() {
                return Err(format!(
                    "Project Color effect {} cannot target video layers",
                    effect.id
                ));
            }
            validate_group_ids(&request.target_group_ids)?;
            validate_project_color_effect_targets(
                snapshot,
                &fixtures_by_id,
                &request.fixture_ids,
                &request.target_group_ids,
                &format!("Color effect {}", effect.id),
            )?;
            continue;
        }
        if matches!(effect.effect_type, EffectKind::Chaser) {
            let request = effect.chaser.as_ref().ok_or_else(|| {
                format!(
                    "Project effect {} is missing its Chaser request body",
                    effect.id
                )
            })?;
            if !effect.video_targets.is_empty() {
                return Err(format!(
                    "Project Chaser effect {} cannot target video layers",
                    effect.id
                ));
            }
            let (fixture_ids, target_group_ids) = validate_project_chaser_effect_targets(
                snapshot,
                &fixtures_by_id,
                request,
                &format!("Chaser effect {}", effect.id),
            )?;
            if effect.fixture_ids != fixture_ids || effect.target_group_ids != target_group_ids {
                return Err(format!(
                    "Project Chaser effect {} target summary does not match its ordered steps",
                    effect.id
                ));
            }
            continue;
        }
        if matches!(effect.effect_type, EffectKind::Move) {
            let request = effect.move_effect.as_ref().ok_or_else(|| {
                format!(
                    "Project effect {} is missing its Move request body",
                    effect.id
                )
            })?;
            if !effect.video_targets.is_empty() {
                return Err(format!(
                    "Project Move effect {} cannot target video layers",
                    effect.id
                ));
            }
            validate_group_ids(&request.target_group_ids)?;
            validate_project_move_effect_targets(
                snapshot,
                &fixtures_by_id,
                &request.fixture_ids,
                &request.target_group_ids,
                &format!("Move effect {}", effect.id),
            )?;
            if effect.fixture_ids != request.fixture_ids
                || effect.target_group_ids != request.target_group_ids
            {
                return Err(format!(
                    "Project Move effect {} target summary does not match its request body",
                    effect.id
                ));
            }
            continue;
        }
        let has_light_targets =
            !effect.fixture_ids.is_empty() || !effect.target_group_ids.is_empty();
        let has_video_targets = !effect.video_targets.is_empty();
        if !has_light_targets && !has_video_targets {
            return Err(format!(
                "Project effect {} requires a light or video target",
                effect.id
            ));
        }
        if has_light_targets && effect.attribute.trim().is_empty() {
            return Err(format!(
                "Project effect {} has light targets but no attribute",
                effect.id
            ));
        }
        validate_group_ids(&effect.target_group_ids)?;
        validate_project_effect_fixture_targets(
            snapshot,
            &fixtures_by_id,
            &effect.fixture_ids,
            &effect.target_group_ids,
            &effect.attribute,
            &format!("effect {}", effect.id),
        )?;
    }

    Ok(())
}

fn validate_project_fixture_attribute_values_for_target(
    fixtures_by_id: &HashMap<FixtureId, &PatchedFixtureSummary>,
    fixture_id: FixtureId,
    values: &[protocol::AttributeValueSummary],
    owner_label: &str,
) -> Result<(), String> {
    let fixture = fixtures_by_id
        .get(&fixture_id)
        .ok_or_else(|| format!("Project {owner_label} references missing fixture {fixture_id}"))?;
    let mut seen_attributes = HashSet::new();
    for value in values {
        if !seen_attributes.insert(value.attribute.as_str()) {
            return Err(format!(
                "Project {owner_label} fixture target {} contains duplicate attribute '{}'",
                fixture_id, value.attribute
            ));
        }
        validate_project_fixture_attribute_ref(
            fixtures_by_id,
            fixture_id,
            &value.attribute,
            owner_label,
        )?;
    }
    if values.is_empty() {
        return Err(format!(
            "Project {owner_label} fixture target {} has no attribute values",
            fixture.id
        ));
    }
    Ok(())
}

fn validate_project_fixture_attribute_ref(
    fixtures_by_id: &HashMap<FixtureId, &PatchedFixtureSummary>,
    fixture_id: FixtureId,
    attribute: &str,
    owner_label: &str,
) -> Result<(), String> {
    if attribute.trim().is_empty() {
        return Err(format!("Project {owner_label} has an empty attribute"));
    }
    let fixture = fixtures_by_id
        .get(&fixture_id)
        .ok_or_else(|| format!("Project {owner_label} references missing fixture {fixture_id}"))?;
    if !fixture
        .controls
        .iter()
        .any(|control| control.attribute == attribute)
    {
        return Err(format!(
            "Project {owner_label} references unavailable attribute '{}' on fixture {} '{}'",
            attribute, fixture.id, fixture.label
        ));
    }
    Ok(())
}

fn validate_project_effect_fixture_targets(
    snapshot: &EngineSnapshot,
    fixtures_by_id: &HashMap<FixtureId, &PatchedFixtureSummary>,
    fixture_ids: &[FixtureId],
    target_group_ids: &[String],
    attribute: &str,
    owner_label: &str,
) -> Result<(), String> {
    validate_project_unique_refs(owner_label, fixture_ids)?;
    for fixture_id in fixture_ids {
        validate_project_fixture_attribute_ref(
            fixtures_by_id,
            *fixture_id,
            attribute,
            owner_label,
        )?;
    }
    for group_id in target_group_ids {
        let group_fixtures = snapshot
            .fixtures
            .iter()
            .filter(|fixture| {
                fixture
                    .group_ids
                    .iter()
                    .any(|candidate| group_matches(candidate, group_id))
            })
            .collect::<Vec<_>>();
        if group_fixtures.is_empty() {
            return Err(format!(
                "Project {owner_label} references missing fixture group '{group_id}'"
            ));
        }
        if !group_fixtures.iter().any(|fixture| {
            fixture
                .controls
                .iter()
                .any(|control| control.attribute == attribute)
        }) {
            return Err(format!(
                "Project {owner_label} group '{group_id}' has no fixtures exposing attribute {attribute}"
            ));
        }
    }
    Ok(())
}

fn validate_project_color_effect_targets(
    snapshot: &EngineSnapshot,
    fixtures_by_id: &HashMap<FixtureId, &PatchedFixtureSummary>,
    fixture_ids: &[FixtureId],
    target_group_ids: &[String],
    owner_label: &str,
) -> Result<(), String> {
    validate_project_unique_refs(owner_label, fixture_ids)?;
    let mut target_ids = HashSet::new();
    for fixture_id in fixture_ids {
        if !fixtures_by_id.contains_key(fixture_id) {
            return Err(format!(
                "Project {owner_label} references missing fixture {fixture_id}"
            ));
        }
        target_ids.insert(*fixture_id);
    }

    for group_id in target_group_ids {
        let mut matched = false;
        for fixture in &snapshot.fixtures {
            if fixture
                .group_ids
                .iter()
                .any(|candidate| group_matches(candidate, group_id))
            {
                matched = true;
                target_ids.insert(fixture.id);
            }
        }
        if !matched {
            return Err(format!(
                "Project {owner_label} references missing fixture group '{group_id}'"
            ));
        }
    }

    let compatible_count = target_ids
        .iter()
        .filter(|fixture_id| {
            fixtures_by_id
                .get(fixture_id)
                .is_some_and(|fixture| fixture_supports_color_effect(fixture))
        })
        .count();
    if compatible_count == 0 {
        return Err(format!(
            "Project {owner_label} has no fixtures with an RGB, RGBW, CMY, HSV, or colored-wheel control system"
        ));
    }
    Ok(())
}

fn validate_project_move_effect_targets(
    snapshot: &EngineSnapshot,
    fixtures_by_id: &HashMap<FixtureId, &PatchedFixtureSummary>,
    fixture_ids: &[FixtureId],
    target_group_ids: &[String],
    owner_label: &str,
) -> Result<(), String> {
    validate_project_unique_refs(owner_label, fixture_ids)?;
    let mut target_ids = HashSet::new();
    for fixture_id in fixture_ids {
        if !fixtures_by_id.contains_key(fixture_id) {
            return Err(format!(
                "Project {owner_label} references missing fixture {fixture_id}"
            ));
        }
        target_ids.insert(*fixture_id);
    }
    for group_id in target_group_ids {
        let mut matched = false;
        for fixture in &snapshot.fixtures {
            if fixture
                .group_ids
                .iter()
                .any(|candidate| group_matches(candidate, group_id))
            {
                matched = true;
                target_ids.insert(fixture.id);
            }
        }
        if !matched {
            return Err(format!(
                "Project {owner_label} references missing fixture group '{group_id}'"
            ));
        }
    }
    if !target_ids.iter().any(|fixture_id| {
        fixtures_by_id
            .get(fixture_id)
            .is_some_and(|fixture| fixture_supports_move_effect(fixture))
    }) {
        return Err(format!(
            "Project {owner_label} has no fixtures with paired Pan and Tilt controls"
        ));
    }
    Ok(())
}

fn validate_project_chaser_effect_targets(
    snapshot: &EngineSnapshot,
    fixtures_by_id: &HashMap<FixtureId, &PatchedFixtureSummary>,
    request: &ChaserEffectRequest,
    owner_label: &str,
) -> Result<(Vec<FixtureId>, Vec<String>), String> {
    let mut fixture_ids = Vec::new();
    let mut target_group_ids = Vec::new();
    let mut seen_fixture_ids = HashSet::new();
    let mut seen_group_ids = HashSet::new();
    let mut resolved_target_ids = HashSet::new();
    let mut has_group_reference = false;

    for (step_index, step) in request.steps.iter().enumerate() {
        validate_project_unique_refs(
            &format!("{owner_label} step {} fixture", step_index + 1),
            &step.fixture_ids,
        )?;
        validate_group_ids(&step.target_group_ids)?;
        for fixture_id in &step.fixture_ids {
            if !fixtures_by_id.contains_key(fixture_id) {
                return Err(format!(
                    "Project {owner_label} step {} references missing fixture {fixture_id}",
                    step_index + 1
                ));
            }
            resolved_target_ids.insert(*fixture_id);
            if seen_fixture_ids.insert(*fixture_id) {
                fixture_ids.push(*fixture_id);
            }
        }
        for group_id in &step.target_group_ids {
            has_group_reference = true;
            for fixture in &snapshot.fixtures {
                if fixture
                    .group_ids
                    .iter()
                    .any(|candidate| group_matches(candidate, group_id))
                {
                    resolved_target_ids.insert(fixture.id);
                }
            }
            if seen_group_ids.insert(group_id.clone()) {
                target_group_ids.push(group_id.clone());
            }
        }
    }

    if resolved_target_ids.is_empty() && !has_group_reference {
        return Err(format!(
            "Project {owner_label} resolves to no fixture targets"
        ));
    }
    for feature in &request.features {
        let feature_key = normalize_custom_attribute_name(&feature.attribute);
        let compatible = resolved_target_ids.iter().any(|fixture_id| {
            fixtures_by_id.get(fixture_id).is_some_and(|fixture| {
                fixture.controls.iter().any(|control| {
                    control.attribute.eq_ignore_ascii_case(&feature.attribute)
                        || normalize_custom_attribute_name(&control.attribute) == feature_key
                })
            })
        });
        if !compatible && !has_group_reference {
            return Err(format!(
                "Project {owner_label} feature '{}' is unavailable on every targeted fixture",
                feature.attribute
            ));
        }
    }

    Ok((fixture_ids, target_group_ids))
}

fn fixture_supports_move_effect(fixture: &PatchedFixtureSummary) -> bool {
    let mut has_pan = false;
    let mut has_tilt = false;
    for control in &fixture.controls {
        let normalized = normalize_custom_attribute_name(&control.attribute);
        has_pan |= normalized.contains("pan") && !normalized.contains("tilt");
        has_tilt |= normalized.contains("tilt");
    }
    has_pan && has_tilt
}

fn fixture_supports_color_effect(fixture: &PatchedFixtureSummary) -> bool {
    let has_control = |aliases: &[&str]| {
        aliases.iter().any(|alias| {
            fixture
                .controls
                .iter()
                .any(|control| normalize_custom_attribute_name(&control.attribute) == *alias)
        })
    };
    let has_rgb = has_control(&[
        "colorred",
        "colourred",
        "red",
        "coloraddr",
        "colouraddr",
        "colorrgbred",
    ]) && has_control(&[
        "colorgreen",
        "colourgreen",
        "green",
        "coloraddg",
        "colouraddg",
        "colorrgbgreen",
    ]) && has_control(&[
        "colorblue",
        "colourblue",
        "blue",
        "coloraddb",
        "colouraddb",
        "colorrgbblue",
    ]);
    let has_cmy = has_control(&[
        "colorsubc",
        "coloursubc",
        "colorcyan",
        "colourcyan",
        "cyan",
        "colorrgbcyan",
    ]) && has_control(&[
        "colorsubm",
        "coloursubm",
        "colormagenta",
        "colourmagenta",
        "magenta",
        "colorrgbmagenta",
    ]) && has_control(&[
        "colorsuby",
        "coloursuby",
        "coloryellow",
        "colouryellow",
        "yellow",
        "colorrgbyellow",
    ]);
    let has_hsv = has_control(&[
        "colorhsvhue",
        "colourhsvhue",
        "colorhsbhue",
        "colourhsbhue",
        "colorhue",
        "colourhue",
        "hue",
        "hsbhue",
    ]) && has_control(&[
        "colorhsvsaturation",
        "colourhsvsaturation",
        "colorhsbsaturation",
        "colourhsbsaturation",
        "colorsaturation",
        "coloursaturation",
        "saturation",
        "hsbsaturation",
    ]) && has_control(&[
        "colorhsvvalue",
        "colourhsvvalue",
        "colorhsbbrightness",
        "colourhsbbrightness",
        "colorbrightness",
        "colourbrightness",
        "value",
        "brightness",
        "hsbbrightness",
    ]);

    has_rgb
        || has_cmy
        || has_hsv
        || fixture
            .controls
            .iter()
            .any(control_supports_colored_wheel_effect)
}

fn control_supports_colored_wheel_effect(control: &AttributeControl) -> bool {
    let normalized = normalize_custom_attribute_name(&control.attribute);
    if !normalized.contains("color") && !normalized.contains("colour") {
        return false;
    }
    let mut physical_slots = HashSet::new();
    for function in &control.functions {
        if let Some(identity) = color_wheel_function_identity(function, control) {
            physical_slots.insert(identity);
            if physical_slots.len() >= 2 {
                return true;
            }
        }
    }
    false
}

fn color_wheel_function_identity(
    function: &protocol::ChannelFunctionSummary,
    control: &AttributeControl,
) -> Option<String> {
    let color = function
        .wheel_slot_color
        .as_deref()
        .and_then(normalized_color_wheel_hex)
        .or_else(|| named_color_wheel_key(function, control).map(str::to_string))?;
    let physical_slot = function
        .wheel_slot
        .as_deref()
        .or(function.wheel_slot_name.as_deref())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_ascii_lowercase);
    Some(physical_slot.map_or_else(|| format!("color:{color}"), |slot| format!("slot:{slot}")))
}

fn named_color_wheel_key(
    function: &protocol::ChannelFunctionSummary,
    control: &AttributeControl,
) -> Option<&'static str> {
    let text = format!(
        "{} {} {} {} {} {}",
        function.name,
        function.attribute,
        function.wheel_slot.as_deref().unwrap_or_default(),
        function.wheel_slot_name.as_deref().unwrap_or_default(),
        function.parent_function.as_deref().unwrap_or_default(),
        control.channel_name,
    )
    .to_ascii_lowercase();
    let tokens = text
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect::<HashSet<_>>();
    if tokens.contains("open") || tokens.contains("clear") || tokens.contains("white") {
        Some("white")
    } else if tokens.contains("red") {
        Some("red")
    } else if tokens.contains("green") {
        Some("green")
    } else if tokens.contains("blue") {
        Some("blue")
    } else if tokens.contains("cyan") || tokens.contains("aqua") {
        Some("cyan")
    } else if tokens.contains("magenta") || tokens.contains("pink") {
        Some("magenta")
    } else if tokens.contains("yellow") {
        Some("yellow")
    } else if tokens.contains("amber") || tokens.contains("orange") {
        Some("amber")
    } else if tokens.contains("purple") || tokens.contains("violet") || tokens.contains("uv") {
        Some("purple")
    } else {
        None
    }
}

fn normalized_color_wheel_hex(value: &str) -> Option<String> {
    let value = value.trim().strip_prefix('#')?;
    (value.len() == 6 && value.bytes().all(|byte| byte.is_ascii_hexdigit()))
        .then(|| value.to_ascii_lowercase())
}

fn validate_project_custom_profiles(profiles: &[FixtureProfileSummary]) -> Result<(), String> {
    let mut seen = HashSet::new();
    for profile in profiles {
        let source_path = profile.source_path.trim();
        if source_path.is_empty() {
            return Err("Project custom profile has an empty source path".to_string());
        }
        if !seen.insert(source_path.to_string()) {
            return Err(format!(
                "Project contains duplicate custom profile source path {source_path}"
            ));
        }
        if profile.manufacturer.trim().is_empty() {
            return Err(format!(
                "Project custom profile {source_path} has an empty manufacturer"
            ));
        }
        if profile.name.trim().is_empty() {
            return Err(format!(
                "Project custom profile {source_path} has an empty name"
            ));
        }
        if profile.dmx_modes.is_empty() {
            return Err(format!(
                "Project custom profile {source_path} has no DMX modes"
            ));
        }
        for mode in &profile.dmx_modes {
            if mode.name.trim().is_empty() {
                return Err(format!(
                    "Project custom profile {source_path} has an empty DMX mode name"
                ));
            }
            fixture_controls_footprint(&mode.controls).ok_or_else(|| {
                format!(
                    "Project custom profile {source_path} mode '{}' has no DMX channel offsets",
                    mode.name
                )
            })?;
            validate_geometry_collection(
                &format!("custom profile {source_path} mode '{}'", mode.name),
                &profile.geometries,
                &mode.controls,
            )?;
        }
    }
    Ok(())
}

fn validate_project_custom_profile_refs(
    snapshot: &EngineSnapshot,
    profiles: &[FixtureProfileSummary],
) -> Result<(), String> {
    let custom_profile_paths = profiles
        .iter()
        .map(|profile| profile.source_path.as_str())
        .collect::<HashSet<_>>();
    for fixture in &snapshot.fixtures {
        let source_path = fixture.profile_source_path.trim();
        if source_path.starts_with("memory://custom/")
            && !custom_profile_paths.contains(source_path)
        {
            return Err(format!(
                "Project fixture {} '{}' references missing custom profile {}",
                fixture.id, fixture.label, source_path
            ));
        }
    }
    Ok(())
}

fn validate_project_video_graph(snapshot: &EngineSnapshot) -> Result<(), String> {
    let layer_ids = snapshot
        .video
        .layers
        .iter()
        .map(|layer| layer.id)
        .collect::<HashSet<_>>();
    let composition_ids = snapshot
        .video
        .compositions
        .iter()
        .map(|composition| composition.id)
        .collect::<HashSet<_>>();
    let outputs_by_id = snapshot
        .video
        .outputs
        .iter()
        .map(|output| (output.id, output))
        .collect::<HashMap<_, _>>();
    let node_graph_ids = snapshot
        .node_graphs
        .iter()
        .map(|graph| graph.id)
        .collect::<HashSet<_>>();

    validate_project_isf_source_budget(project_isf_source_bytes(snapshot)?)?;
    for layer in &snapshot.video.layers {
        if layer.label.trim().is_empty() {
            return Err(format!(
                "Project video layer {} has an empty label",
                layer.id
            ));
        }
        validate_project_video_source(
            &layer.source,
            &format!("video layer {} '{}'", layer.id, layer.label),
        )?;
        validate_project_video_layer_state(&layer.state, &format!("video layer {}", layer.id))?;
        if let Some(effect) = &layer.isf_effect {
            sanitize_video_isf_effect(effect.clone()).map_err(|error| {
                format!(
                    "Project video layer {} ISF effect is invalid: {error}",
                    layer.id
                )
            })?;
        }
    }

    for composition in &snapshot.video.compositions {
        if composition.label.trim().is_empty() {
            return Err(format!(
                "Project video composition {} has an empty label",
                composition.id
            ));
        }
        validate_project_unique_refs(
            &format!("video composition {} layer", composition.id),
            &composition.layer_ids,
        )?;
        validate_project_unique_refs(
            &format!("video composition {} output", composition.id),
            &composition.output_ids,
        )?;
        for layer_id in &composition.layer_ids {
            if !layer_ids.contains(layer_id) {
                return Err(format!(
                    "Project video composition {} '{}' references missing video layer {}",
                    composition.id, composition.label, layer_id
                ));
            }
        }
        for output_id in &composition.output_ids {
            let Some(output) = outputs_by_id.get(output_id) else {
                return Err(format!(
                    "Project video composition {} '{}' references missing video output {}",
                    composition.id, composition.label, output_id
                ));
            };
            if output.composition_id != composition.id {
                return Err(format!(
                    "Project video composition {} '{}' lists output {} routed to composition {}",
                    composition.id, composition.label, output.id, output.composition_id
                ));
            }
        }
    }

    for output in &snapshot.video.outputs {
        if output.label.trim().is_empty() {
            return Err(format!(
                "Project video output {} has an empty label",
                output.id
            ));
        }
        if output.width == 0 || output.height == 0 {
            return Err(format!(
                "Project video output {} '{}' has invalid resolution {}x{}",
                output.id, output.label, output.width, output.height
            ));
        }
        if !composition_ids.contains(&output.composition_id) {
            return Err(format!(
                "Project video output {} '{}' routes to missing composition {}",
                output.id, output.label, output.composition_id
            ));
        }
        if !output.opacity.is_finite() {
            return Err(format!(
                "Project video output {} '{}' has non-finite opacity",
                output.id, output.label
            ));
        }
        validate_video_output_mapping(&output.mapping)?;
    }

    validate_project_external_video_backends(snapshot)?;

    for cue in &snapshot.cues {
        for target in &cue.video_targets {
            validate_project_video_layer_ref(&layer_ids, target.layer_id, "cue", cue.id)?;
            validate_project_video_layer_state(
                &target.state,
                &format!("cue {} video layer target {}", cue.id, target.layer_id),
            )?;
        }
        for target in &cue.video_output_targets {
            if !outputs_by_id.contains_key(&target.output_id) {
                return Err(format!(
                    "Project cue {} references missing video output {}",
                    cue.id, target.output_id
                ));
            }
            if !target.opacity.is_finite() {
                return Err(format!(
                    "Project cue {} video output target {} has non-finite opacity",
                    cue.id, target.output_id
                ));
            }
        }
        let cue_node_graph_ids = cue
            .node_graph_targets
            .iter()
            .map(|target| target.graph_id)
            .collect::<Vec<_>>();
        validate_project_unique_refs(&format!("cue {} node graph", cue.id), &cue_node_graph_ids)?;
        for target in &cue.node_graph_targets {
            if !node_graph_ids.contains(&target.graph_id) {
                return Err(format!(
                    "Project cue {} references missing node graph {}",
                    cue.id, target.graph_id
                ));
            }
        }
    }

    for automation in &snapshot.timeline.video_automations {
        validate_project_video_layer_ref(
            &layer_ids,
            automation.layer_id,
            "timeline video automation",
            automation.id,
        )?;
        if automation.keyframes.is_empty() {
            return Err(format!(
                "Project timeline video automation {} requires at least one keyframe",
                automation.id
            ));
        }
        if automation
            .keyframes
            .iter()
            .any(|keyframe| !keyframe.value.is_finite())
        {
            return Err(format!(
                "Project timeline video automation {} has non-finite keyframe values",
                automation.id
            ));
        }
        validate_project_video_keyframes(
            &automation.keyframes,
            &format!("timeline video automation {}", automation.id),
        )?;
    }

    for effect in &snapshot.effects {
        validate_video_effect_targets(&effect.video_targets)?;
        for target in &effect.video_targets {
            for layer_id in &target.layer_ids {
                validate_project_video_layer_ref(&layer_ids, *layer_id, "effect", effect.id)?;
            }
        }
    }

    let mut mapping_preset_labels = HashSet::new();
    for preset in &snapshot.video.mapping_presets {
        let label = preset.label.trim();
        if label.is_empty() {
            return Err("Project video output mapping preset has an empty label".to_string());
        }
        if !mapping_preset_labels.insert(label.to_string()) {
            return Err(format!(
                "Project contains duplicate video output mapping preset label {label}"
            ));
        }
        validate_video_output_mapping(&preset.mapping)?;
    }

    Ok(())
}

fn validate_project_video_source(source: &VideoSourceSummary, label: &str) -> Result<(), String> {
    if source
        .codec
        .as_deref()
        .is_some_and(|codec| codec.trim().is_empty())
    {
        return Err(format!("Project {label} source has an empty codec"));
    }

    if let Some(metadata) = source.metadata {
        validate_project_video_source_metadata(&metadata, label)?;
    }

    match source.kind {
        VideoSourceKind::File => {
            if source.path.as_deref().unwrap_or_default().trim().is_empty() {
                return Err(format!("Project {label} file source requires a file path"));
            }
        }
        VideoSourceKind::StillImage => {
            if source.path.as_deref().unwrap_or_default().trim().is_empty() {
                return Err(format!(
                    "Project {label} still image source requires a still image path"
                ));
            }
        }
        VideoSourceKind::Camera
        | VideoSourceKind::ScreenCapture
        | VideoSourceKind::Ndi
        | VideoSourceKind::Spout
        | VideoSourceKind::Syphon => {
            let (_, feature_label) =
                video_input_backend(&source.kind).expect("external source kind must have backend");
            if source.name.as_deref().unwrap_or_default().trim().is_empty() {
                return Err(format!(
                    "Project {label} requires a source name for {feature_label}"
                ));
            }
        }
    }

    Ok(())
}

fn validate_project_video_source_metadata(
    metadata: &protocol::VideoMediaMetadata,
    label: &str,
) -> Result<(), String> {
    if metadata.width.is_some_and(|width| width == 0) {
        return Err(format!("Project {label} source has invalid metadata width"));
    }
    if metadata.height.is_some_and(|height| height == 0) {
        return Err(format!(
            "Project {label} source has invalid metadata height"
        ));
    }
    if metadata
        .frame_rate
        .is_some_and(|frame_rate| !frame_rate.is_finite() || frame_rate <= 0.0)
    {
        return Err(format!(
            "Project {label} source has invalid metadata frame rate"
        ));
    }
    Ok(())
}

fn validate_project_external_video_backends(snapshot: &EngineSnapshot) -> Result<(), String> {
    for layer in &snapshot.video.layers {
        let Some((_, feature_label)) = video_input_backend(&layer.source.kind) else {
            continue;
        };
        if layer
            .source
            .name
            .as_deref()
            .unwrap_or_default()
            .trim()
            .is_empty()
        {
            return Err(format!(
                "Project video layer {} '{}' requires a source name for {feature_label}",
                layer.id, layer.label
            ));
        }
    }

    for output in &snapshot.video.outputs {
        let Some((_, feature_label)) = video_output_backend(&output.kind) else {
            continue;
        };
        if output
            .endpoint_name
            .as_deref()
            .unwrap_or_default()
            .trim()
            .is_empty()
        {
            return Err(format!(
                "Project video output {} '{}' requires an endpoint name for {feature_label}",
                output.id, output.label
            ));
        }
    }

    Ok(())
}

fn validate_project_node_graphs(snapshot: &EngineSnapshot) -> Result<(), String> {
    for graph in &snapshot.node_graphs {
        validate_node_graph_summary(graph, snapshot)?;
    }
    Ok(())
}

fn validate_project_unique_refs(label: &str, ids: &[u64]) -> Result<(), String> {
    let mut seen = HashSet::new();
    for id in ids {
        if !seen.insert(*id) {
            return Err(format!("Project contains duplicate {label} reference {id}"));
        }
    }
    Ok(())
}

