fn validate_project_effect_body(effect: &EffectSummary) -> Result<(), String> {
    match effect.effect_type {
        EffectKind::Lfo | EffectKind::PositionWave => {
            if effect.color.is_some()
                || effect.chaser.is_some()
                || effect.move_effect.is_some()
                || effect.value.is_some()
            {
                return Err(format!(
                    "Project effect {} contains a body for another effect kind",
                    effect.id
                ));
            }
        }
        EffectKind::Color => {
            if effect.chaser.is_some() {
                return Err(format!(
                    "Project Color effect {} contains a Chaser body",
                    effect.id
                ));
            }
            if effect.move_effect.is_some() {
                return Err(format!(
                    "Project Color effect {} contains a Move body",
                    effect.id
                ));
            }
            if effect.value.is_some() {
                return Err(format!(
                    "Project Color effect {} contains a Value body",
                    effect.id
                ));
            }
        }
        EffectKind::Chaser => {
            if effect.color.is_some() {
                return Err(format!(
                    "Project Chaser effect {} contains a Color body",
                    effect.id
                ));
            }
            if effect.move_effect.is_some() {
                return Err(format!(
                    "Project Chaser effect {} contains a Move body",
                    effect.id
                ));
            }
            if effect.value.is_some() {
                return Err(format!(
                    "Project Chaser effect {} contains a Value body",
                    effect.id
                ));
            }
            let request = effect.chaser.as_ref().ok_or_else(|| {
                format!(
                    "Project Chaser effect {} is missing its request body",
                    effect.id
                )
            })?;
            let first_feature = request
                .features
                .first()
                .ok_or_else(|| format!("Project Chaser effect {} has no features", effect.id))?;
            let scalar_body_matches = effect.label == request.label
                && effect.attribute == first_feature.attribute
                && effect.low == first_feature.low
                && effect.high == first_feature.high
                && effect.period_ms == Some(request.step_duration_ms)
                && effect.clock_sync == request.clock_sync
                && effect.phase == request.phase
                && effect.blend_mode == request.blend_mode
                && effect.shape == protocol::LfoShape::Square
                && effect.origin.is_none()
                && effect.direction.is_none()
                && effect.speed.is_none()
                && effect.wavelength.is_none();
            if !scalar_body_matches {
                return Err(format!(
                    "Project Chaser effect {} summary fields do not match its request body",
                    effect.id
                ));
            }
        }
        EffectKind::Move => {
            if effect.color.is_some() {
                return Err(format!(
                    "Project Move effect {} contains a Color body",
                    effect.id
                ));
            }
            if effect.chaser.is_some() {
                return Err(format!(
                    "Project Move effect {} contains a Chaser body",
                    effect.id
                ));
            }
            if effect.value.is_some() {
                return Err(format!(
                    "Project Move effect {} contains a Value body",
                    effect.id
                ));
            }
            let request = effect.move_effect.as_ref().ok_or_else(|| {
                format!(
                    "Project Move effect {} is missing its request body",
                    effect.id
                )
            })?;
            let scalar_body_matches = effect.label == request.label
                && effect.fixture_ids == request.fixture_ids
                && effect.target_group_ids == request.target_group_ids
                && effect.attribute == "Pan/Tilt"
                && effect.video_targets.is_empty()
                && effect.shape == protocol::LfoShape::Sine
                && effect.period_ms == Some(request.period_ms)
                && effect.clock_sync == request.clock_sync
                && effect.low == 0
                && effect.high == u16::MAX
                && effect.phase == request.phase
                && effect.blend_mode == request.blend_mode
                && effect.origin.is_none()
                && effect.direction.is_none()
                && effect.speed.is_none()
                && effect.wavelength.is_none();
            if !scalar_body_matches {
                return Err(format!(
                    "Project Move effect {} summary fields do not match its request body",
                    effect.id
                ));
            }
        }
        EffectKind::Value => {
            if effect.color.is_some() {
                return Err(format!(
                    "Project Value effect {} contains a Color body",
                    effect.id
                ));
            }
            if effect.chaser.is_some() {
                return Err(format!(
                    "Project Value effect {} contains a Chaser body",
                    effect.id
                ));
            }
            if effect.move_effect.is_some() {
                return Err(format!(
                    "Project Value effect {} contains a Move body",
                    effect.id
                ));
            }
            let request = effect.value.as_ref().ok_or_else(|| {
                format!(
                    "Project Value effect {} is missing its request body",
                    effect.id
                )
            })?;
            let scalar_body_matches = effect.label == request.label
                && effect.fixture_ids == request.fixture_ids
                && effect.target_group_ids == request.target_group_ids
                && effect.attribute == request.attribute
                && effect.video_targets.is_empty()
                && effect.shape == protocol::LfoShape::Sine
                && effect.period_ms == Some(request.period_ms)
                && effect.clock_sync == request.clock_sync
                && effect.low == request.low
                && effect.high == request.high
                && effect.phase == request.phase
                && effect.blend_mode == request.blend_mode
                && effect.origin.is_none()
                && effect.direction.is_none()
                && effect.speed.is_none()
                && effect.wavelength.is_none();
            if !scalar_body_matches {
                return Err(format!(
                    "Project Value effect {} summary fields do not match its request body",
                    effect.id
                ));
            }
        }
    }
    let preset = effect_summary_to_preset(effect)
        .map_err(|error| format!("Project effect {} is invalid: {error}", effect.id))?;
    validate_effect_preset(&preset)
        .map_err(|error| format!("Project effect {} is invalid: {error}", effect.id))
}

fn validate_project_video_layer_ref(
    layer_ids: &HashSet<VideoLayerId>,
    layer_id: VideoLayerId,
    owner_label: &str,
    owner_id: u64,
) -> Result<(), String> {
    if layer_ids.contains(&layer_id) {
        Ok(())
    } else {
        Err(format!(
            "Project {owner_label} {owner_id} references missing video layer {layer_id}"
        ))
    }
}

fn validate_project_video_layer_state(state: &VideoLayerState, label: &str) -> Result<(), String> {
    let transform = state.transform;
    let color = state.color;
    let fx = state.fx;
    let values = [
        state.opacity,
        state.speed,
        state.bpm_sync.ratio,
        state.bpm_sync.loop_bars,
        transform.x,
        transform.y,
        transform.scale_x,
        transform.scale_y,
        transform.rotation_deg,
        transform.crop_left,
        transform.crop_top,
        transform.crop_right,
        transform.crop_bottom,
        color.brightness,
        color.contrast,
        color.hue_deg,
        color.saturation,
        color.gamma,
        fx.pixelate,
        fx.blur,
        fx.glow,
        fx.edge,
        fx.key_red,
        fx.key_green,
        fx.key_blue,
        fx.key_threshold,
    ];
    if values.iter().any(|value| !value.is_finite()) {
        return Err(format!("Project {label} has non-finite video state values"));
    }
    if transform.scale_x <= 0.0 || transform.scale_y <= 0.0 {
        return Err(format!(
            "Project {label} transform scale must be greater than 0"
        ));
    }
    if state.bpm_sync.ratio <= 0.0 || state.bpm_sync.loop_bars <= 0.0 {
        return Err(format!(
            "Project {label} BPM sync ratio and loop bars must be greater than 0"
        ));
    }
    if state.loop_enabled && state.loop_end_ms <= state.loop_start_ms {
        return Err(format!(
            "Project {label} loop end must be greater than loop start"
        ));
    }
    validate_project_video_cue_points(state, label)?;
    Ok(())
}

fn validate_project_video_cue_points(state: &VideoLayerState, label: &str) -> Result<(), String> {
    let mut seen_positions = HashSet::new();
    for cue_point in &state.cue_points {
        if !seen_positions.insert(cue_point.position_ms) {
            return Err(format!(
                "Project {label} contains duplicate video cue point at {}ms",
                cue_point.position_ms
            ));
        }
        if let Some(color) = &cue_point.color {
            validate_video_cue_point_color(color)
                .map_err(|error| format!("Project {label} cue point color is invalid: {error}"))?;
        }
    }

    let mut seen_legacy_positions = HashSet::new();
    for position_ms in &state.cue_points_ms {
        if !seen_legacy_positions.insert(*position_ms) {
            return Err(format!(
                "Project {label} contains duplicate legacy video cue point at {position_ms}ms"
            ));
        }
    }
    Ok(())
}

fn effect_summary_to_preset(effect: &EffectSummary) -> Result<EffectPreset, String> {
    match effect.effect_type {
        EffectKind::Lfo => {
            let period_ms = effect
                .period_ms
                .ok_or_else(|| "LFO effect summary is missing period_ms".to_string())?;
            Ok(EffectPreset {
                version: 1,
                effect_type: EffectKind::Lfo,
                enabled: effect.enabled,
                lfo: Some(LfoEffectRequest {
                    label: effect.label.clone(),
                    fixture_ids: effect.fixture_ids.clone(),
                    target_group_ids: effect.target_group_ids.clone(),
                    attribute: effect.attribute.clone(),
                    video_targets: effect.video_targets.clone(),
                    shape: effect.shape.clone(),
                    period_ms,
                    clock_sync: effect.clock_sync,
                    low: effect.low,
                    high: effect.high,
                    phase: effect.phase,
                    blend_mode: effect.blend_mode.clone(),
                }),
                position_wave: None,
                color: None,
                chaser: None,
                move_effect: None,
                value: None,
            })
        }
        EffectKind::PositionWave => {
            let origin = effect
                .origin
                .ok_or_else(|| "Position wave effect summary is missing origin".to_string())?;
            let direction = effect
                .direction
                .ok_or_else(|| "Position wave effect summary is missing direction".to_string())?;
            let speed = effect
                .speed
                .ok_or_else(|| "Position wave effect summary is missing speed".to_string())?;
            let wavelength = effect
                .wavelength
                .ok_or_else(|| "Position wave effect summary is missing wavelength".to_string())?;
            Ok(EffectPreset {
                version: 1,
                effect_type: EffectKind::PositionWave,
                enabled: effect.enabled,
                lfo: None,
                position_wave: Some(PositionWaveEffectRequest {
                    label: effect.label.clone(),
                    fixture_ids: effect.fixture_ids.clone(),
                    target_group_ids: effect.target_group_ids.clone(),
                    attribute: effect.attribute.clone(),
                    video_targets: effect.video_targets.clone(),
                    shape: effect.shape.clone(),
                    origin,
                    direction,
                    speed,
                    wavelength,
                    clock_sync: effect.clock_sync,
                    low: effect.low,
                    high: effect.high,
                    phase: effect.phase,
                    blend_mode: effect.blend_mode.clone(),
                }),
                color: None,
                chaser: None,
                move_effect: None,
                value: None,
            })
        }
        EffectKind::Color => {
            let request = effect
                .color
                .clone()
                .ok_or_else(|| "Color effect summary is missing its request body".to_string())?;
            Ok(EffectPreset {
                version: 1,
                effect_type: EffectKind::Color,
                enabled: effect.enabled,
                lfo: None,
                position_wave: None,
                color: Some(request),
                chaser: None,
                move_effect: None,
                value: None,
            })
        }
        EffectKind::Chaser => {
            let request = effect
                .chaser
                .clone()
                .ok_or_else(|| "Chaser effect summary is missing its request body".to_string())?;
            Ok(EffectPreset {
                version: 1,
                effect_type: EffectKind::Chaser,
                enabled: effect.enabled,
                lfo: None,
                position_wave: None,
                color: None,
                chaser: Some(request),
                move_effect: None,
                value: None,
            })
        }
        EffectKind::Move => {
            let request = effect
                .move_effect
                .clone()
                .ok_or_else(|| "Move effect summary is missing its request body".to_string())?;
            Ok(EffectPreset {
                version: 1,
                effect_type: EffectKind::Move,
                enabled: effect.enabled,
                lfo: None,
                position_wave: None,
                color: None,
                chaser: None,
                move_effect: Some(request),
                value: None,
            })
        }
        EffectKind::Value => {
            let request = effect
                .value
                .clone()
                .ok_or_else(|| "Value effect summary is missing its request body".to_string())?;
            Ok(EffectPreset {
                version: 1,
                effect_type: EffectKind::Value,
                enabled: effect.enabled,
                lfo: None,
                position_wave: None,
                color: None,
                chaser: None,
                move_effect: None,
                value: Some(request),
            })
        }
    }
}

fn effect_params_snapshot_from_summary(
    effect: &EffectSummary,
) -> Result<EffectParamsSnapshot, String> {
    let preset = effect_summary_to_preset(effect)?;
    match effect.effect_type {
        EffectKind::Lfo => preset
            .lfo
            .map(EffectParamsSnapshot::Lfo)
            .ok_or_else(|| "LFO effect summary is missing its request body".to_string()),
        EffectKind::PositionWave => preset
            .position_wave
            .map(EffectParamsSnapshot::PositionWave)
            .ok_or_else(|| "Position wave effect summary is missing its request body".to_string()),
        EffectKind::Color => preset
            .color
            .map(EffectParamsSnapshot::Color)
            .ok_or_else(|| "Color effect summary is missing its request body".to_string()),
        EffectKind::Chaser => preset
            .chaser
            .map(EffectParamsSnapshot::Chaser)
            .ok_or_else(|| "Chaser effect summary is missing its request body".to_string()),
        EffectKind::Move => preset
            .move_effect
            .map(EffectParamsSnapshot::Move)
            .ok_or_else(|| "Move effect summary is missing its request body".to_string()),
        EffectKind::Value => preset
            .value
            .map(EffectParamsSnapshot::Value)
            .ok_or_else(|| "Value effect summary is missing its request body".to_string()),
    }
}

fn apply_lfo_effect_target_override(
    mut request: LfoEffectRequest,
    target_override: &EffectTargetOverride,
) -> LfoEffectRequest {
    request.fixture_ids = target_override.fixture_ids.clone();
    request.target_group_ids = target_override.target_group_ids.clone();
    request.video_targets = target_override.video_targets.clone();
    request.attribute = overridden_light_attribute(target_override);
    request
}

fn apply_position_wave_effect_target_override(
    mut request: PositionWaveEffectRequest,
    target_override: &EffectTargetOverride,
) -> PositionWaveEffectRequest {
    request.fixture_ids = target_override.fixture_ids.clone();
    request.target_group_ids = target_override.target_group_ids.clone();
    request.video_targets = target_override.video_targets.clone();
    request.attribute = overridden_light_attribute(target_override);
    request
}

fn apply_color_effect_target_override(
    mut request: ColorEffectRequest,
    target_override: &EffectTargetOverride,
) -> Result<ColorEffectRequest, String> {
    validate_color_effect_target_override(target_override)?;
    request.fixture_ids = target_override.fixture_ids.clone();
    request.target_group_ids = target_override.target_group_ids.clone();
    Ok(request)
}

fn apply_chaser_effect_target_override(
    mut request: ChaserEffectRequest,
    target_override: &EffectTargetOverride,
    snapshot: &EngineSnapshot,
) -> Result<ChaserEffectRequest, String> {
    validate_chaser_effect_target_override(target_override)?;
    let fixture_ids = resolve_chaser_effect_target_override(target_override, snapshot)?;
    let mut target_cursor = 0_usize;
    request.steps = request
        .steps
        .into_iter()
        .map(|step| {
            let target_slot_count = step.fixture_ids.len() + step.target_group_ids.len();
            if target_slot_count == 0 {
                return ChaserStep {
                    fixture_ids: Vec::new(),
                    target_group_ids: Vec::new(),
                    level: step.level,
                };
            }

            let mut remapped_fixture_ids = Vec::new();
            for _ in 0..target_slot_count.min(fixture_ids.len()) {
                let fixture_id = fixture_ids[target_cursor % fixture_ids.len()];
                target_cursor = target_cursor.saturating_add(1);
                if !remapped_fixture_ids.contains(&fixture_id) {
                    remapped_fixture_ids.push(fixture_id);
                }
            }
            ChaserStep {
                fixture_ids: remapped_fixture_ids,
                target_group_ids: Vec::new(),
                level: step.level,
            }
        })
        .collect();
    if request.features.len() == 1 && !target_override.attribute.trim().is_empty() {
        request.features[0].attribute = overridden_light_attribute(target_override);
    }
    Ok(request)
}

fn apply_move_effect_target_override(
    mut request: MoveEffectRequest,
    target_override: &EffectTargetOverride,
) -> Result<MoveEffectRequest, String> {
    validate_move_effect_target_override(target_override)?;
    request.fixture_ids = target_override.fixture_ids.clone();
    request.target_group_ids = target_override.target_group_ids.clone();
    Ok(request)
}

fn apply_value_effect_target_override(
    mut request: ValueEffectRequest,
    target_override: &EffectTargetOverride,
) -> ValueEffectRequest {
    request.fixture_ids = target_override.fixture_ids.clone();
    request.target_group_ids = target_override.target_group_ids.clone();
    request.attribute = overridden_light_attribute(target_override);
    request
}

fn apply_fixture_index_chaser_effect_target_override(
    mut request: ChaserEffectRequest,
    target_override: &EffectTargetOverride,
    snapshot: &EngineSnapshot,
) -> Result<ChaserEffectRequest, String> {
    validate_chaser_effect_target_override(target_override)?;
    let fixture_ids = resolve_chaser_effect_target_override(target_override, snapshot)?;
    let single_fixture_target = fixture_ids.len() == 1;

    let active_level = request
        .steps
        .iter()
        .map(|step| step.level)
        .max()
        .filter(|level| *level > 0)
        .unwrap_or(u16::MAX);
    request.steps = fixture_ids
        .into_iter()
        .map(|fixture_id| ChaserStep {
            fixture_ids: vec![fixture_id],
            target_group_ids: Vec::new(),
            level: active_level,
        })
        .collect();
    if request.steps.len() == 1 {
        request.steps.push(ChaserStep {
            fixture_ids: Vec::new(),
            target_group_ids: Vec::new(),
            level: 0,
        });
    }
    if single_fixture_target {
        request.active_step_count = 1;
        request.wings = 1;
    } else {
        request.active_step_count = request
            .active_step_count
            .max(1)
            .min(request.steps.len().min(64) as u16);
        request.wings = request.wings.max(1).min(request.steps.len().min(16) as u8);
    }
    if request.features.len() == 1 && !target_override.attribute.trim().is_empty() {
        request.features[0].attribute = overridden_light_attribute(target_override);
    }
    Ok(request)
}

fn resolve_chaser_effect_target_override(
    target_override: &EffectTargetOverride,
    snapshot: &EngineSnapshot,
) -> Result<Vec<FixtureId>, String> {
    validate_effect_target_references(snapshot, &target_override.fixture_ids, &[])?;

    let mut fixture_ids = Vec::new();
    let mut seen_fixture_ids = HashSet::new();
    for fixture_id in &target_override.fixture_ids {
        if seen_fixture_ids.insert(*fixture_id) {
            fixture_ids.push(*fixture_id);
        }
    }
    for group_id in &target_override.target_group_ids {
        let mut matched = false;
        for fixture in &snapshot.fixtures {
            if fixture
                .group_ids
                .iter()
                .any(|candidate| group_matches(candidate, group_id))
            {
                matched = true;
                if seen_fixture_ids.insert(fixture.id) {
                    fixture_ids.push(fixture.id);
                }
            }
        }
        if !matched {
            return Err(format!(
                "Group '{group_id}' was not found or has no fixtures"
            ));
        }
    }
    if fixture_ids.is_empty() {
        return Err("Chaser effects require at least one resolved fixture target".to_string());
    }
    Ok(fixture_ids)
}

fn validate_color_effect_target_override(
    target_override: &EffectTargetOverride,
) -> Result<(), String> {
    if target_override.fixture_ids.is_empty() && target_override.target_group_ids.is_empty() {
        return Err("Color effects require a fixture, selection, or group target".to_string());
    }
    if !target_override.video_targets.is_empty() {
        return Err("Color effects cannot target video parameters".to_string());
    }
    validate_group_ids(&target_override.target_group_ids)
}

fn validate_chaser_effect_target_override(
    target_override: &EffectTargetOverride,
) -> Result<(), String> {
    if !target_override.video_targets.is_empty() {
        return Err("Chaser effects cannot target video parameters".to_string());
    }
    if target_override.fixture_ids.is_empty() && target_override.target_group_ids.is_empty() {
        return Err("Chaser effects require a fixture, selection, or group target".to_string());
    }
    validate_group_ids(&target_override.target_group_ids)
}

fn validate_move_effect_target_override(
    target_override: &EffectTargetOverride,
) -> Result<(), String> {
    if !target_override.video_targets.is_empty() {
        return Err("Move effects cannot target video parameters".to_string());
    }
    if target_override.fixture_ids.is_empty() && target_override.target_group_ids.is_empty() {
        return Err("Move effects require a fixture, selection, or group target".to_string());
    }
    validate_group_ids(&target_override.target_group_ids)
}

fn overridden_light_attribute(target_override: &EffectTargetOverride) -> String {
    if target_override.fixture_ids.is_empty() && target_override.target_group_ids.is_empty() {
        String::new()
    } else {
        target_override.attribute.trim().to_string()
    }
}

fn validate_effect_target_override(target_override: &EffectTargetOverride) -> Result<(), String> {
    let has_light_targets =
        !target_override.fixture_ids.is_empty() || !target_override.target_group_ids.is_empty();
    let has_video_targets = !target_override.video_targets.is_empty();
    if !has_light_targets && !has_video_targets {
        return Err("At least one fixture, group, or video layer must be targeted".to_string());
    }
    if has_light_targets && target_override.attribute.trim().is_empty() {
        return Err("Effect attribute is required".to_string());
    }
    validate_group_ids(&target_override.target_group_ids)?;
    validate_video_effect_targets(&target_override.video_targets)?;
    Ok(())
}

fn validate_effect_target_override_for_preset(
    preset: &EffectPreset,
    target_override: &EffectTargetOverride,
) -> Result<(), String> {
    match preset.effect_type {
        EffectKind::Color => validate_color_effect_target_override(target_override),
        EffectKind::Chaser => {
            preset
                .chaser
                .as_ref()
                .ok_or_else(|| "Chaser effect preset is missing its request body".to_string())?;
            validate_chaser_effect_target_override(target_override)
        }
        EffectKind::Move => {
            preset
                .move_effect
                .as_ref()
                .ok_or_else(|| "Move effect preset is missing its request body".to_string())?;
            validate_move_effect_target_override(target_override)
        }
        EffectKind::Value => {
            preset
                .value
                .as_ref()
                .ok_or_else(|| "Value effect preset is missing its request body".to_string())?;
            validate_effect_target_override(target_override)
        }
        EffectKind::Lfo | EffectKind::PositionWave => {
            validate_effect_target_override(target_override)
        }
    }
}

fn validate_node_graph_summary(
    graph: &NodeGraphSummary,
    snapshot: &EngineSnapshot,
) -> Result<(), String> {
    if graph.id == 0 {
        return Err("Node graph id must be greater than 0".to_string());
    }
    if graph.label.trim().is_empty() {
        return Err("Node graph label is required".to_string());
    }
    if graph.nodes.is_empty() {
        return Err("Node graph requires at least one node".to_string());
    }

    let mut node_ids = HashSet::new();
    for node in &graph.nodes {
        if node.id == 0 {
            return Err(format!("Node graph '{}' contains node id 0", graph.label));
        }
        if !node_ids.insert(node.id) {
            return Err(format!(
                "Node graph '{}' contains duplicate node id {}",
                graph.label, node.id
            ));
        }
        if node.label.trim().is_empty() {
            return Err(format!(
                "Node graph '{}' node {} has an empty label",
                graph.label, node.id
            ));
        }
        if !node.x.is_finite() || !node.y.is_finite() {
            return Err(format!(
                "Node graph '{}' node {} has non-finite coordinates",
                graph.label, node.id
            ));
        }

        match node.kind {
            NodeGraphNodeKind::Lfo => {
                if node.position_wave.is_some()
                    || node.audio.is_some()
                    || node.transform.is_some()
                    || node.output.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' LFO node {} contains a non-LFO body",
                        graph.label, node.id
                    ));
                }
                let Some(lfo) = &node.lfo else {
                    return Err(format!(
                        "Node graph '{}' LFO node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                if lfo.period_ms < 10 {
                    return Err(format!(
                        "Node graph '{}' LFO node {} period must be at least 10ms",
                        graph.label, node.id
                    ));
                }
                if !lfo.phase.is_finite() || !lfo.amplitude.is_finite() || !lfo.bias.is_finite() {
                    return Err(format!(
                        "Node graph '{}' LFO node {} has non-finite values",
                        graph.label, node.id
                    ));
                }
                if let Some(clock_sync) = lfo.clock_sync {
                    if !clock_sync.beats.is_finite() || clock_sync.beats <= 0.0 {
                        return Err(format!(
                            "Node graph '{}' LFO node {} clock sync beats must be greater than 0",
                            graph.label, node.id
                        ));
                    }
                }
            }
            NodeGraphNodeKind::PositionWave => {
                if node.lfo.is_some()
                    || node.audio.is_some()
                    || node.transform.is_some()
                    || node.output.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' position wave node {} contains a non-position-wave body",
                        graph.label, node.id
                    ));
                }
                let Some(wave) = &node.position_wave else {
                    return Err(format!(
                        "Node graph '{}' position wave node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                if !wave.origin.x.is_finite()
                    || !wave.origin.y.is_finite()
                    || !wave.origin.z.is_finite()
                    || !wave.direction.x.is_finite()
                    || !wave.direction.y.is_finite()
                    || !wave.direction.z.is_finite()
                    || !wave.speed.is_finite()
                    || !wave.wavelength.is_finite()
                    || !wave.phase.is_finite()
                {
                    return Err(format!(
                        "Node graph '{}' position wave node {} has non-finite values",
                        graph.label, node.id
                    ));
                }
                if wave.wavelength.abs() < 0.001 {
                    return Err(format!(
                        "Node graph '{}' position wave node {} wavelength must be at least 0.001",
                        graph.label, node.id
                    ));
                }
                if let Some(clock_sync) = wave.clock_sync {
                    if !clock_sync.beats.is_finite() || clock_sync.beats <= 0.0 {
                        return Err(format!(
                            "Node graph '{}' position wave node {} clock sync beats must be greater than 0",
                            graph.label, node.id
                        ));
                    }
                }
            }
            NodeGraphNodeKind::Audio => {
                if node.lfo.is_some()
                    || node.position_wave.is_some()
                    || node.transform.is_some()
                    || node.output.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' audio node {} contains a non-audio body",
                        graph.label, node.id
                    ));
                }
                let Some(audio) = &node.audio else {
                    return Err(format!(
                        "Node graph '{}' audio node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                if !audio.gain.is_finite() || !audio.bias.is_finite() {
                    return Err(format!(
                        "Node graph '{}' audio node {} has non-finite values",
                        graph.label, node.id
                    ));
                }
            }
            NodeGraphNodeKind::Transform => {
                if node.lfo.is_some()
                    || node.position_wave.is_some()
                    || node.audio.is_some()
                    || node.output.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' transform node {} contains a non-transform body",
                        graph.label, node.id
                    ));
                }
                let Some(transform) = &node.transform else {
                    return Err(format!(
                        "Node graph '{}' transform node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                if !transform.amount.is_finite()
                    || !transform.min.is_finite()
                    || !transform.max.is_finite()
                {
                    return Err(format!(
                        "Node graph '{}' transform node {} has non-finite values",
                        graph.label, node.id
                    ));
                }
                if matches!(transform.op, NodeGraphTransformOp::Clamp)
                    && transform.min > transform.max
                {
                    return Err(format!(
                        "Node graph '{}' clamp node {} min must be <= max",
                        graph.label, node.id
                    ));
                }
            }
            NodeGraphNodeKind::Output => {
                if node.lfo.is_some()
                    || node.position_wave.is_some()
                    || node.audio.is_some()
                    || node.transform.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' output node {} contains a non-output body",
                        graph.label, node.id
                    ));
                }
                let Some(output) = &node.output else {
                    return Err(format!(
                        "Node graph '{}' output node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                let has_light_targets =
                    !output.fixture_ids.is_empty() || !output.target_group_ids.is_empty();
                if has_light_targets && output.attribute.trim().is_empty() {
                    return Err(format!(
                        "Node graph '{}' output node {} is missing its light attribute",
                        graph.label, node.id
                    ));
                }
                if !has_light_targets && output.video_targets.is_empty() {
                    return Err(format!(
                        "Node graph '{}' output node {} requires a light or video target",
                        graph.label, node.id
                    ));
                }
                validate_group_ids(&output.target_group_ids)?;
                validate_video_effect_targets(&output.video_targets)?;
                let fixtures_by_id = snapshot
                    .fixtures
                    .iter()
                    .map(|fixture| (fixture.id, fixture))
                    .collect::<HashMap<_, _>>();
                validate_project_effect_fixture_targets(
                    snapshot,
                    &fixtures_by_id,
                    &output.fixture_ids,
                    &output.target_group_ids,
                    &output.attribute,
                    &format!("node graph '{}' output node {}", graph.label, node.id),
                )?;
                validate_effect_target_references(
                    snapshot,
                    &output.fixture_ids,
                    &output.video_targets,
                )?;
            }
        }
    }

    for edge in &graph.edges {
        if !node_ids.contains(&edge.from_node) || !node_ids.contains(&edge.to_node) {
            return Err(format!(
                "Node graph '{}' contains an edge with a missing node reference",
                graph.label
            ));
        }
        if edge.from_port.trim().is_empty() || edge.to_port.trim().is_empty() {
            return Err(format!(
                "Node graph '{}' contains an edge with an empty port",
                graph.label
            ));
        }
    }

    Ok(())
}

fn validate_node_graph_preset_file(
    file: &NodeGraphPresetFile,
    snapshot: &EngineSnapshot,
) -> Result<(), String> {
    if file.version != 1 {
        return Err(format!(
            "Unsupported node graph preset version {}",
            file.version
        ));
    }
    validate_app_name("node graph preset", &file.app)?;
    validate_node_graph_summary(&file.graph, snapshot)
}

fn validate_effect_preset(preset: &EffectPreset) -> Result<(), String> {
    if preset.version != 1 {
        return Err(format!(
            "Unsupported effect preset version {}",
            preset.version
        ));
    }
    match preset.effect_type {
        EffectKind::Lfo => {
            if preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
            {
                return Err("LFO effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .lfo
                .as_ref()
                .ok_or_else(|| "LFO effect preset is missing its request body".to_string())?;
            validate_lfo_effect_request(request)?;
        }
        EffectKind::PositionWave => {
            if preset.lfo.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
            {
                return Err(
                    "Position wave effect preset must not contain another effect body".to_string(),
                );
            }
            let request = preset.position_wave.as_ref().ok_or_else(|| {
                "Position wave effect preset is missing its request body".to_string()
            })?;
            validate_position_wave_effect_request(request)?;
        }
        EffectKind::Color => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
            {
                return Err("Color effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .color
                .as_ref()
                .ok_or_else(|| "Color effect preset is missing its request body".to_string())?;
            validate_color_effect_request(request)?;
        }
        EffectKind::Chaser => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
            {
                return Err("Chaser effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .chaser
                .as_ref()
                .ok_or_else(|| "Chaser effect preset is missing its request body".to_string())?;
            validate_chaser_effect_request(request)?;
        }
        EffectKind::Move => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.value.is_some()
            {
                return Err("Move effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .move_effect
                .as_ref()
                .ok_or_else(|| "Move effect preset is missing its request body".to_string())?;
            validate_move_effect_request(request)?;
        }
        EffectKind::Value => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
            {
                return Err("Value effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .value
                .as_ref()
                .ok_or_else(|| "Value effect preset is missing its request body".to_string())?;
            validate_value_effect_request(request)?;
        }
    }
    Ok(())
}

fn validate_effect_target_references(
    snapshot: &EngineSnapshot,
    fixture_ids: &[FixtureId],
    video_targets: &[VideoEffectTarget],
) -> Result<(), String> {
    for fixture_id in fixture_ids {
        if !snapshot
            .fixtures
            .iter()
            .any(|fixture| fixture.id == *fixture_id)
        {
            return Err(format!("Fixture {fixture_id} was not found"));
        }
    }
    for target in video_targets {
        validate_video_layer_ids(snapshot, &target.layer_ids)?;
    }
    Ok(())
}

fn validate_fixture_preset<'a>(
    preset: &FixturePreset,
    manufacturer: &str,
    profile_name: &str,
    mode_name: &str,
    valid_attributes: impl IntoIterator<Item = &'a str>,
) -> Result<(), String> {
    if preset.version != 1 {
        return Err(format!("Unsupported preset version {}", preset.version));
    }
    if preset.manufacturer != manufacturer
        || preset.profile_name != profile_name
        || preset.mode_name != mode_name
    {
        return Err(format!(
            "Preset is for {} {} / {}, but selected fixture is {} {} / {}",
            preset.manufacturer,
            preset.profile_name,
            preset.mode_name,
            manufacturer,
            profile_name,
            mode_name
        ));
    }
    let valid_attributes = valid_attributes.into_iter().collect::<HashSet<_>>();
    let mut preset_attributes = HashSet::new();
    for value in &preset.values {
        if !preset_attributes.insert(value.attribute.as_str()) {
            return Err(format!(
                "Preset contains duplicate attribute '{}'",
                value.attribute
            ));
        }
    }
    if let Some(value) = preset
        .values
        .iter()
        .find(|value| !valid_attributes.contains(value.attribute.as_str()))
    {
        return Err(format!(
            "Preset attribute '{}' is not available on the selected fixture mode",
            value.attribute
        ));
    }
    Ok(())
}

fn compatible_fixture_preset_targets(
    preset: &FixturePreset,
    fixtures: Vec<&PatchedFixtureSummary>,
) -> (Vec<FixtureId>, usize) {
    let mut fixture_ids = Vec::new();
    let mut skipped_count = 0usize;
    for fixture in fixtures {
        let compatible = validate_fixture_preset(
            preset,
            &fixture.manufacturer,
            &fixture.profile_name,
            &fixture.mode_name,
            fixture
                .controls
                .iter()
                .map(|control| control.attribute.as_str()),
        )
        .is_ok();
        if compatible {
            fixture_ids.push(fixture.id);
        } else {
            skipped_count += 1;
        }
    }
    (fixture_ids, skipped_count)
}

#[tauri::command]
fn get_snapshot(state: State<'_, AppState>) -> EngineSnapshot {
    state.engine.snapshot()
}

fn engine_snapshot_delta(before: &EngineSnapshot, after: &EngineSnapshot) -> EngineSnapshotDelta {
    macro_rules! changed {
        ($field:ident) => {
            (before.$field != after.$field).then(|| after.$field.clone())
        };
    }
    EngineSnapshotDelta {
        fixtures: changed!(fixtures),
        cues: changed!(cues),
        cue_lists: changed!(cue_lists),
        palettes: changed!(palettes),
        playback_executors: changed!(playback_executors),
        playback_master: (before.playback_master != after.playback_master)
            .then_some(after.playback_master),
        active_cue_id: (before.active_cue_id != after.active_cue_id).then_some(after.active_cue_id),
        active_fade: (before.active_fade != after.active_fade).then(|| after.active_fade.clone()),
        programmer: changed!(programmer),
        timeline: changed!(timeline),
        video: changed!(video),
        effects: changed!(effects),
        node_graphs: changed!(node_graphs),
        output: changed!(output),
        dmx_outputs: changed!(dmx_outputs),
        lighting_master: (before.lighting_master != after.lighting_master)
            .then_some(after.lighting_master),
        submasters: changed!(submasters),
        blackout: (before.blackout != after.blackout).then_some(after.blackout),
        clock: changed!(clock),
        stage_map: changed!(stage_map),
        stage_map_presets: changed!(stage_map_presets),
        stage_objects: changed!(stage_objects),
        dmx_preview: changed!(dmx_preview),
        dmx_previews: changed!(dmx_previews),
        telemetry: changed!(telemetry),
    }
}

#[tauri::command]
fn get_snapshot_delta(
    state: State<'_, AppState>,
    client_revision: Option<u64>,
) -> Result<EngineSnapshotSyncResponse, String> {
    let current = state.engine.snapshot();
    let mut sync = state
        .snapshot_sync
        .lock()
        .map_err(|_| "Snapshot synchronization lock was poisoned".to_string())?;
    let can_send_delta = client_revision == Some(sync.revision) && sync.last_snapshot.is_some();
    sync.revision = sync.revision.wrapping_add(1).max(1);
    let revision = sync.revision;
    let response = if can_send_delta {
        EngineSnapshotSyncResponse {
            revision,
            full: None,
            delta: sync
                .last_snapshot
                .as_ref()
                .map(|before| engine_snapshot_delta(before, &current)),
        }
    } else {
        EngineSnapshotSyncResponse {
            revision,
            full: Some(current.clone()),
            delta: None,
        }
    };
    sync.last_snapshot = Some(current);
    Ok(response)
}

