    #[test]
    fn video_output_mapping_preset_file_serializes_and_validates() {
        let file = VideoOutputMappingPresetFile {
            version: 1,
            app: APP_NAME.to_string(),
            preset: VideoOutputMappingPresetSummary {
                label: "Front Projector".to_string(),
                mapping: VideoOutputMapping {
                    stage_x: 2.5,
                    stage_z: -1.0,
                    aspect_ratio: 16.0 / 9.0,
                    lens_distortion: 0.25,
                    edge_blend_left: 0.2,
                    edge_blend_gamma: 1.8,
                    black_level: 0.05,
                    mask_point_count: 3,
                    mask_softness: 0.02,
                    mask_points: [
                        protocol::VideoMaskPoint { x: 0.5, y: 0.05 },
                        protocol::VideoMaskPoint { x: 0.95, y: 0.95 },
                        protocol::VideoMaskPoint { x: 0.05, y: 0.95 },
                        protocol::VideoMaskPoint::default(),
                        protocol::VideoMaskPoint::default(),
                        protocol::VideoMaskPoint::default(),
                        protocol::VideoMaskPoint::default(),
                        protocol::VideoMaskPoint::default(),
                    ],
                    ..Default::default()
                },
            },
        };

        validate_video_output_mapping_preset_file(&file).unwrap();
        let json = serde_json::to_string_pretty(&file).unwrap();
        let parsed: VideoOutputMappingPresetFile = serde_json::from_str(&json).unwrap();
        assert_eq!(parsed.preset.label, "Front Projector");
        assert!((parsed.preset.mapping.stage_x - 2.5).abs() < f32::EPSILON);
        assert!((parsed.preset.mapping.stage_z + 1.0).abs() < f32::EPSILON);
        assert!((parsed.preset.mapping.aspect_ratio - 16.0 / 9.0).abs() < f32::EPSILON);
        assert!((parsed.preset.mapping.edge_blend_left - 0.2).abs() < f32::EPSILON);
        assert!((parsed.preset.mapping.black_level - 0.05).abs() < f32::EPSILON);
        assert_eq!(parsed.preset.mapping.mask_point_count, 3);

        let mut legacy = serde_json::to_value(&file).unwrap();
        let mapping = legacy["preset"]["mapping"].as_object_mut().unwrap();
        for field in [
            "edge_blend_left",
            "edge_blend_right",
            "edge_blend_top",
            "edge_blend_bottom",
            "edge_blend_gamma",
            "black_level",
            "mask_point_count",
            "mask_invert",
            "mask_softness",
            "mask_points",
            "bitmap_mask_width",
            "bitmap_mask_height",
            "bitmap_mask_luma_words",
        ] {
            mapping.remove(field);
        }
        let legacy: VideoOutputMappingPresetFile = serde_json::from_value(legacy).unwrap();
        assert_eq!(legacy.preset.mapping.edge_blend_left, 0.0);
        assert_eq!(legacy.preset.mapping.edge_blend_gamma, 2.2);
        assert_eq!(legacy.preset.mapping.mask_point_count, 0);
        assert_eq!(legacy.preset.mapping.bitmap_mask_width, 0);
        assert_eq!(legacy.preset.mapping.bitmap_mask_height, 0);
        assert_eq!(legacy.preset.mapping.bitmap_mask_luma_words, [0; 32]);

        let unsupported = VideoOutputMappingPresetFile {
            version: 2,
            ..file.clone()
        };
        assert!(validate_video_output_mapping_preset_file(&unsupported)
            .unwrap_err()
            .contains("version"));

        let wrong_app = VideoOutputMappingPresetFile {
            app: "Other".to_string(),
            ..file
        };
        assert!(validate_video_output_mapping_preset_file(&wrong_app)
            .unwrap_err()
            .contains("Unsupported projector map app"));
    }

    #[test]
    fn project_file_serializes_snapshot_as_pretty_json() {
        let project = ProjectFile {
            version: 1,
            app: APP_NAME.to_string(),
            custom_profiles: Vec::new(),
            snapshot: EngineSnapshot {
                blackout: true,
                timeline: protocol::TimelineSnapshot {
                    audio: Some(AudioAnalysisSummary {
                        path: "C:/media/show.wav".to_string(),
                        sample_rate: 48_000,
                        channels: 2,
                        duration_ms: 5_000,
                        estimated_bpm: Some(120.0),
                        waveform: vec![protocol::AudioWaveformPoint {
                            time_ms: 0,
                            peak: 0.5,
                            rms: 0.25,
                        }],
                        spectrum: Vec::new(),
                        beats: vec![0, 500, 1_000],
                    }),
                    ..protocol::TimelineSnapshot::default()
                },
                ..EngineSnapshot::default()
            },
        };

        let json = serde_json::to_string_pretty(&project).unwrap();
        let parsed: ProjectFile = serde_json::from_str(&json).unwrap();

        assert!(json.contains("\"version\": 1"));
        assert_eq!(parsed.app, APP_NAME);
        assert!(parsed.snapshot.blackout);
        assert_eq!(parsed.snapshot.dmx_outputs.len(), 1);
        let mut legacy = serde_json::to_value(&project).unwrap();
        legacy["snapshot"]["timeline"]["audio"]
            .as_object_mut()
            .unwrap()
            .remove("spectrum");
        let legacy: ProjectFile = serde_json::from_value(legacy).unwrap();
        assert!(legacy.snapshot.timeline.audio.unwrap().spectrum.is_empty());
        assert_eq!(
            parsed
                .snapshot
                .timeline
                .audio
                .as_ref()
                .and_then(|audio| audio.estimated_bpm),
            Some(120.0)
        );
    }

    #[test]
    fn project_file_v1_accepts_unknown_fields_and_defaults_added_fields() {
        let mut sample_value: Value = serde_json::from_str(PHASE1_SAMPLE_PROJECT_JSON).unwrap();
        let root = sample_value.as_object_mut().unwrap();
        root.insert("future_top_level".to_string(), json!({ "enabled": true }));
        let snapshot = root
            .get_mut("snapshot")
            .and_then(Value::as_object_mut)
            .unwrap();
        snapshot.insert("future_snapshot_field".to_string(), json!(42));
        snapshot["fixtures"][0]
            .as_object_mut()
            .unwrap()
            .insert("future_fixture_field".to_string(), json!("ignored"));
        let sample_project: ProjectFile = serde_json::from_value(sample_value).unwrap();
        validate_project_file(&sample_project).unwrap();
        assert!(sample_project
            .snapshot
            .cues
            .iter()
            .all(|cue| cue.authored_beats.is_none()));
        assert!(sample_project.snapshot.timeline.events.iter().all(|event| {
            event.time_beats.is_none()
                && event.duration_beats.is_none()
                && !event.conform_to_tempo
                && !event.loop_fill
                && event.rate.is_none()
        }));

        let mut legacy_value = serde_json::to_value(ProjectFile {
            version: PROJECT_FILE_VERSION,
            app: APP_NAME.to_string(),
            custom_profiles: Vec::new(),
            snapshot: EngineSnapshot::default(),
        })
        .unwrap();
        let legacy_root = legacy_value.as_object_mut().unwrap();
        legacy_root.remove("custom_profiles");
        let legacy_snapshot = legacy_root["snapshot"].as_object_mut().unwrap();
        legacy_snapshot.remove("node_graphs");
        legacy_snapshot.remove("stage_map");
        legacy_snapshot.remove("stage_map_presets");
        legacy_snapshot.remove("stage_objects");
        legacy_snapshot.remove("dmx_previews");
        legacy_snapshot.remove("palettes");
        legacy_snapshot.remove("playback_executors");
        legacy_snapshot.remove("playback_master");

        let project: ProjectFile = serde_json::from_value(legacy_value).unwrap();
        validate_project_file(&project).unwrap();

        assert!(project.custom_profiles.is_empty());
        assert!(project.snapshot.node_graphs.is_empty());
        assert_eq!(
            project.snapshot.stage_map,
            protocol::StageMapConfig::default()
        );
        assert!(project.snapshot.stage_map_presets.is_empty());
        assert!(project.snapshot.stage_objects.is_empty());
        assert!(project.snapshot.dmx_previews.is_empty());
        assert!(project.snapshot.palettes.is_empty());
        assert_eq!(
            project.snapshot.playback_executors,
            vec![protocol::PlaybackExecutorSummary::default()]
        );
        assert_eq!(project.snapshot.playback_master, 1.0);
    }

    #[test]
    fn project_snapshot_for_save_drops_volatile_runtime_state() {
        let mut snapshot = EngineSnapshot::default();
        snapshot.active_cue_id = Some(7);
        snapshot.active_fade = Some(protocol::ActiveFadeSummary {
            cue_id: 7,
            progress: 0.5,
            remaining_ms: 1_200,
            paused: true,
        });
        snapshot.timeline.playing = true;
        snapshot.timeline.position_ms = 12_345;
        snapshot.video.master_opacity = 0.5;
        snapshot.video.auto_vj.config.seed = 42;
        snapshot.video.auto_vj.config.eligible_layer_ids = vec![5, 7];
        let auto_vj_action = protocol::AutoVjAction {
            sequence: 3,
            boundary_index: 2,
            beat: 8,
            layer_id: 7,
            transition_ms: 500,
            selection_token: 99,
            seed: 42,
            show_revision: 4,
            trigger: protocol::AutoVjTrigger::LiveAudioOnset,
            live_audio_feature_sequence: Some(17),
        };
        snapshot.video.auto_vj.status = protocol::AutoVjStatus {
            mode: protocol::AutoVjMode::Running,
            armed: true,
            hold: false,
            show_revision: 4,
            action_sequence: 3,
            last_consumed_boundary: Some(2),
            next_boundary_beat: Some(12),
            last_action: Some(auto_vj_action.clone()),
            action_log: vec![auto_vj_action],
            fault: None,
            live_audio_beat_counter: 8,
            last_live_audio_feature_sequence: Some(17),
            live_audio_waiting: false,
            live_audio_generation: Some(2),
        };
        let auto_vj_config = snapshot.video.auto_vj.config.clone();
        snapshot.dmx_preview = vec![127; 512];
        snapshot.dmx_previews = vec![protocol::DmxUniversePreview {
            universe: 2,
            values: vec![255; 512],
        }];
        snapshot.telemetry.frame_counter = 99;
        snapshot.telemetry.tick_jitter_p99_us = 850;
        snapshot.telemetry.last_error = Some("send failed".to_string());

        let saved = project_snapshot_for_save(snapshot);

        assert_eq!(saved.active_cue_id, Some(7));
        assert_eq!(saved.active_fade, None);
        assert!(!saved.timeline.playing);
        assert_eq!(saved.timeline.position_ms, 12_345);
        assert_eq!(saved.video.master_opacity, 0.5);
        assert_eq!(saved.video.auto_vj.config, auto_vj_config);
        assert_eq!(
            saved.video.auto_vj.status,
            protocol::AutoVjStatus::default()
        );
        assert!(saved.video.auto_vj.status.action_log.is_empty());
        assert!(saved.dmx_preview.is_empty());
        assert!(saved.dmx_previews.is_empty());
        assert_eq!(saved.telemetry, EngineTelemetry::default());
    }

    #[test]
    fn project_save_reload_uses_authored_video_and_strips_audio_runtime() {
        let mut rendered_layer = project_video_layer(10);
        rendered_layer.state.opacity = 0.9;
        let mut authored_layer = rendered_layer.clone();
        authored_layer.state.opacity = 0.35;

        let mut graph = project_node_graph(3, 1);
        graph.audio_runtime = vec![protocol::NodeGraphAudioRuntimeStatus {
            node_id: 1,
            input_value: 0.8,
            output_value: 0.9,
            source_available: true,
            safety_zeroed: false,
            held: true,
            feature_sequence: Some(42),
        }];
        let rendered_video = protocol::VideoSnapshot {
            layers: vec![rendered_layer],
            ..protocol::VideoSnapshot::default()
        };
        let authored_video = protocol::VideoSnapshot {
            layers: vec![authored_layer],
            ..protocol::VideoSnapshot::default()
        };
        let snapshot = EngineSnapshot {
            video: rendered_video,
            authored_video: Some(authored_video),
            node_graphs: vec![graph],
            ..EngineSnapshot::default()
        };

        let saved = project_snapshot_for_save(snapshot);
        let json = serde_json::to_string(&saved).unwrap();
        let reloaded: EngineSnapshot = serde_json::from_str(&json).unwrap();

        assert_eq!(reloaded.video.layers[0].state.opacity, 0.35);
        assert_eq!(reloaded.authored_video, None);
        assert!(reloaded.node_graphs[0].audio_runtime.is_empty());
        assert!(!json.contains("authored_video"));
        assert!(!json.contains("audio_runtime"));
    }

