    #[test]
    fn project_timeline_layers_legacy_load_and_typed_roundtrip_preserve_track() {
        let mut legacy: ProjectFile = serde_json::from_str(PHASE1_SAMPLE_PROJECT_JSON).unwrap();
        assert!(legacy.snapshot.timeline.layers.is_empty());
        assert!(legacy
            .snapshot
            .timeline
            .events
            .iter()
            .all(|event| event.layer_id.is_none()));
        legacy.snapshot.timeline.events[1].track = TimelineTrackKind::Video;
        validate_project_file(&legacy).unwrap();

        let mut snapshot_to_load = legacy.snapshot.clone();
        snapshot_to_load.output.enabled = false;
        for output in &mut snapshot_to_load.dmx_outputs {
            output.enabled = false;
        }
        let engine = EngineHandle::start(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine.load_project_snapshot(snapshot_to_load).unwrap();

        let persisted_legacy = engine.persistence_snapshot().unwrap();
        assert!(persisted_legacy.timeline.layers.is_empty());
        assert!(persisted_legacy
            .timeline
            .events
            .iter()
            .all(|event| event.layer_id.is_none()));
        assert_eq!(
            persisted_legacy.timeline.events[0].track,
            TimelineTrackKind::Lighting
        );
        assert_eq!(
            persisted_legacy.timeline.events[1].track,
            TimelineTrackKind::Video
        );

        let mut display = engine.snapshot();
        for _ in 0..30 {
            if display.timeline.layers.len() == 2
                && display
                    .timeline
                    .events
                    .iter()
                    .all(|event| event.layer_id.is_some())
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            display = engine.snapshot();
        }
        assert_eq!(
            display
                .timeline
                .layers
                .iter()
                .map(|layer| (layer.id, layer.label.as_str(), layer.order, layer.kind))
                .collect::<Vec<_>>(),
            vec![
                (0, "Lighting", 0, TimelineLayerKind::Lighting),
                (1, "Video", 1, TimelineLayerKind::Video),
            ]
        );
        assert_eq!(display.timeline.events[0].layer_id, Some(0));
        assert_eq!(display.timeline.events[1].layer_id, Some(1));

        let mut typed = legacy;
        typed.snapshot.timeline.layers = vec![
            project_timeline_layer(12, "Video Main", 40, TimelineLayerKind::Video),
            project_timeline_layer(13, "Audio Reference", 20, TimelineLayerKind::Audio),
            project_timeline_layer(11, "Lighting Main", 30, TimelineLayerKind::Lighting),
        ];
        typed.snapshot.timeline.events[0].layer_id = Some(11);
        typed.snapshot.timeline.events[0].track = TimelineTrackKind::Video;
        typed.snapshot.timeline.events[1].layer_id = Some(12);
        typed.snapshot.timeline.events[1].track = TimelineTrackKind::Lighting;
        typed.snapshot = project_snapshot_for_save(typed.snapshot);

        assert_eq!(
            typed
                .snapshot
                .timeline
                .layers
                .iter()
                .map(|layer| (layer.id, layer.order, layer.kind))
                .collect::<Vec<_>>(),
            vec![
                (13, 0, TimelineLayerKind::Audio),
                (11, 1, TimelineLayerKind::Lighting),
                (12, 2, TimelineLayerKind::Video),
            ]
        );
        assert_eq!(
            typed.snapshot.timeline.events[0].track,
            TimelineTrackKind::Lighting
        );
        assert_eq!(
            typed.snapshot.timeline.events[1].track,
            TimelineTrackKind::Video
        );
        validate_project_file(&typed).unwrap();

        let json = project_json_for_write(&typed).unwrap();
        let json_value: Value = serde_json::from_str(&json).unwrap();
        assert_eq!(
            json_value["snapshot"]["timeline"]["events"][0]["layer_id"],
            11
        );
        assert_eq!(
            json_value["snapshot"]["timeline"]["events"][0]["track"],
            "Lighting"
        );
        assert_eq!(
            json_value["snapshot"]["timeline"]["events"][1]["layer_id"],
            12
        );
        assert_eq!(
            json_value["snapshot"]["timeline"]["events"][1]["track"],
            "Video"
        );
        let roundtrip: ProjectFile = serde_json::from_str(&json).unwrap();
        assert_eq!(
            roundtrip.snapshot.timeline.layers,
            typed.snapshot.timeline.layers
        );
        assert_eq!(
            roundtrip.snapshot.timeline.events,
            typed.snapshot.timeline.events
        );
    }

    #[test]
    fn project_identity_colors_sdc_roundtrip_and_legacy_defaults() {
        let mut project = project_with_timeline_scene_blocks();
        if let Some(cue) = project.snapshot.cues.first_mut() {
            cue.color = Some("#ff3366".to_string());
        }
        project
            .snapshot
            .group_colors
            .insert("Front".to_string(), "#22aa88".to_string());

        let json = project_json_for_write(&project).unwrap();
        let roundtrip: ProjectFile = serde_json::from_str(&json).unwrap();
        assert_eq!(
            roundtrip
                .snapshot
                .cues
                .first()
                .and_then(|cue| cue.color.clone()),
            Some("#ff3366".to_string())
        );
        assert_eq!(
            roundtrip
                .snapshot
                .group_colors
                .get("Front")
                .map(String::as_str),
            Some("#22aa88")
        );
        validate_project_file(&roundtrip).unwrap();

        // Legacy projects carry neither field and stay byte-free of them.
        let mut legacy = project_with_timeline_scene_blocks();
        if let Some(cue) = legacy.snapshot.cues.first_mut() {
            cue.color = None;
        }
        legacy.snapshot.group_colors.clear();
        let legacy_json = project_json_for_write(&legacy).unwrap();
        assert!(!legacy_json.contains("\"group_colors\""));
        let legacy_roundtrip: ProjectFile = serde_json::from_str(&legacy_json).unwrap();
        assert!(legacy_roundtrip
            .snapshot
            .cues
            .first()
            .map(|cue| cue.color.is_none())
            .unwrap_or(true));
        assert!(legacy_roundtrip.snapshot.group_colors.is_empty());
    }

    #[test]
    fn project_timeline_audio_clips_sdc_roundtrip_preserves_clips_and_master_fields() {
        let mut project = project_with_timeline_scene_blocks();
        let missing_audio_path = env::temp_dir()
            .join(format!(
                "syndocal-f7-missing-{}-{}",
                std::process::id(),
                current_unix_ms()
            ))
            .join("show-bed.wav")
            .to_string_lossy()
            .to_string();
        project.snapshot.timeline.layers = vec![
            project_timeline_layer(10, "Audio Bed", 0, TimelineLayerKind::Audio),
            project_timeline_layer(11, "Lighting Main", 1, TimelineLayerKind::Lighting),
        ];
        for event in &mut project.snapshot.timeline.events {
            event.layer_id = Some(11);
        }
        project.snapshot.timeline.audio_clips = vec![TimelineAudioClipSummary {
            id: 700,
            layer_id: 10,
            path: missing_audio_path.clone(),
            start_ms: 1_250,
            offset_ms: 200,
            duration_ms: 8_000,
            gain: 0.8,
            fade_in_ms: 500,
            fade_out_ms: 750,
        }];
        project.snapshot.timeline.audio_offset_ms = -125;
        project.snapshot.timeline.audio_muted = true;

        let json = project_json_for_write(&project).unwrap();
        let roundtrip: ProjectFile = serde_json::from_str(&json).unwrap();

        assert_eq!(
            roundtrip.snapshot.timeline.audio_clips,
            project.snapshot.timeline.audio_clips
        );
        assert_eq!(roundtrip.snapshot.timeline.audio_offset_ms, -125);
        assert!(roundtrip.snapshot.timeline.audio_muted);
        validate_project_file(&roundtrip).unwrap();
        let warnings = project_validation_warnings(&roundtrip);
        assert_eq!(warnings.len(), 1);
        assert!(warnings[0].contains("show-bed.wav"));
        assert!(warnings[0].contains("remains loadable for travel"));

        let mut clamped = project.snapshot.clone();
        let clip = &mut clamped.timeline.audio_clips[0];
        clip.path = format!("  {missing_audio_path}  ");
        clip.start_ms = u64::MAX;
        clip.gain = 3.0;
        clip.fade_in_ms = 5_000;
        clip.fade_out_ms = 5_000;
        let clamped = project_snapshot_for_save(clamped);
        let clip = &clamped.timeline.audio_clips[0];
        assert_eq!(clip.path, missing_audio_path);
        assert_eq!(clip.start_ms, u64::MAX - clip.duration_ms);
        assert_eq!(clip.gain, 2.0);
        assert_eq!(clip.fade_in_ms, 5_000);
        assert_eq!(clip.fade_out_ms, 3_000);
    }

    #[test]
    fn project_timeline_audio_legacy_defaults_keep_empty_clips_and_master_path_compatible() {
        let project = project_with_timeline_scene_blocks();
        let mut legacy = serde_json::to_value(project).unwrap();
        let timeline = legacy["snapshot"]["timeline"].as_object_mut().unwrap();
        timeline.remove("audio_clips");
        timeline.remove("audio_offset_ms");
        timeline.remove("audio_muted");

        let legacy: ProjectFile = serde_json::from_value(legacy).unwrap();
        assert!(legacy.snapshot.timeline.audio_clips.is_empty());
        assert_eq!(legacy.snapshot.timeline.audio_offset_ms, 0);
        assert!(!legacy.snapshot.timeline.audio_muted);
        validate_project_file(&legacy).unwrap();

        let mut legacy_master = serde_json::to_value(&legacy).unwrap();
        legacy_master["snapshot"]["timeline"]["audio_offset_ms"] = serde_json::json!(375);
        legacy_master["snapshot"]["timeline"]["audio_muted"] = serde_json::json!(true);
        let legacy_master: ProjectFile = serde_json::from_value(legacy_master).unwrap();
        assert!(legacy_master.snapshot.timeline.audio_clips.is_empty());
        assert_eq!(legacy_master.snapshot.timeline.audio_offset_ms, 375);
        assert!(legacy_master.snapshot.timeline.audio_muted);
        validate_project_file(&legacy_master).unwrap();
    }

