    #[test]
    fn embedded_sample_effect_preset_adds_retargeted_effect_to_engine() {
        let engine = EngineHandle::start(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let profile = custom_fixture_profile_from_request(CustomFixtureProfileRequest {
            manufacturer: "Syndocal".to_string(),
            name: "Preset Target Spot".to_string(),
            mode_name: "8ch".to_string(),
            attributes: vec!["Dimmer".to_string(), "ColorRed".to_string()],
        });
        let fixture_id = engine.allocate_fixture_id();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id,
                request: PatchFixtureRequest {
                    profile_path: profile.source_path.clone(),
                    mode_name: Some("8ch".to_string()),
                    label: "Preset Target".to_string(),
                    universe: 0,
                    address: 1,
                    group_ids: Vec::new(),
                    position: Vec3::default(),
                    rotation: Rotation3::default(),
                },
                profile,
            })
            .unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot
                .fixtures
                .iter()
                .any(|fixture| fixture.id == fixture_id)
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        assert!(snapshot
            .fixtures
            .iter()
            .any(|fixture| fixture.id == fixture_id));

        let (_, pulse_json) = sample_effect_preset_json("pulse").unwrap();
        let pulse: EffectPreset = serde_json::from_str(pulse_json).unwrap();
        let target_override = EffectTargetOverride {
            fixture_ids: vec![fixture_id],
            target_group_ids: Vec::new(),
            attribute: "Dimmer".to_string(),
            video_targets: Vec::new(),
        };
        let effect_id =
            add_effect_preset_to_engine(&engine, pulse, Some(&target_override)).unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.effects.iter().any(|effect| effect.id == effect_id) {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        let effect = snapshot
            .effects
            .iter()
            .find(|effect| effect.id == effect_id)
            .expect("retargeted sample effect should be in the engine snapshot");
        assert_eq!(effect.effect_type, EffectKind::Lfo);
        assert_eq!(effect.fixture_ids, vec![fixture_id]);
        assert!(effect.target_group_ids.is_empty());
        assert_eq!(effect.attribute, "Dimmer");
        assert_eq!(effect.period_ms, Some(500));
        assert_eq!(
            effect.clock_sync,
            Some(protocol::EffectClockSync { beats: 1.0 })
        );
        assert!(effect.enabled);
    }

    #[test]
    fn effect_only_cue_loads_duplicates_recalls_and_cleans_removed_effect_refs() {
        let project = project_with_effect_only_cue();
        validate_project_file(&project).unwrap();
        let engine = EngineHandle::start(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine
            .load_project_snapshot(project.snapshot.clone())
            .unwrap();

        let mut loaded = engine.snapshot();
        for _ in 0..20 {
            if loaded.cues.iter().any(|cue| cue.id == 7)
                && loaded.effects.iter().any(|effect| effect.id == 9)
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            loaded = engine.snapshot();
        }
        assert_eq!(loaded.cues.len(), 1);
        assert_eq!(
            loaded.cues[0].effect_targets,
            project.snapshot.cues[0].effect_targets
        );
        assert!(loaded.effects[0].enabled);

        engine.send(EngineCommand::TriggerCue(7)).unwrap();
        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot
                .effects
                .iter()
                .any(|effect| effect.id == 9 && !effect.enabled)
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        assert!(snapshot
            .effects
            .iter()
            .any(|effect| effect.id == 9 && !effect.enabled));

        engine
            .send(EngineCommand::DuplicateCue {
                source_cue_id: 7,
                cue_id: 8,
                label: "Effect Look Copy".to_string(),
            })
            .unwrap();
        snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.cues.iter().any(|cue| cue.id == 8) {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        let duplicate = snapshot
            .cues
            .iter()
            .find(|cue| cue.id == 8)
            .expect("duplicated effect-only cue");
        assert_eq!(
            duplicate.effect_targets,
            project.snapshot.cues[0].effect_targets
        );

        engine.send(EngineCommand::RemoveEffect(9)).unwrap();
        snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.effects.is_empty()
                && snapshot
                    .cues
                    .iter()
                    .all(|cue| cue.effect_targets.is_empty())
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        assert!(snapshot.effects.is_empty());
        assert!(snapshot
            .cues
            .iter()
            .all(|cue| cue.effect_targets.is_empty()));
    }

